types.schema_json:
{
  "name": "AgenticConfig",
  "package": "cavalier",
  "description": "AgenticConfig is the configuration for the agentic workstation sensor.\n The daemon receives events from coding-agent hooks (PostToolUse,\n SubagentStart, etc.) via a Unix socket, batches them, and publishes\n to EventBus. From there, Aegis ingests the events for topology\n visualization and forensics.",
  "fields": [
    {
      "name": "flush_interval_ms",
      "type": "int32",
      "description": "flush_interval_ms is the max time between event flushes to EventBus. Default: 5000.",
      "default": 5000,
      "constraints": [
        "must be \u003e= 100",
        "must be \u003c= 60000"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 100,
          "source": "annotation"
        },
        {
          "rule": "assert_le",
          "target": "field",
          "value_kind": "int",
          "int_value": 60000,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "batch_size",
      "type": "int32",
      "description": "batch_size is the max events per flush. Default: 100.",
      "default": 100,
      "constraints": [
        "must be \u003e= 1",
        "must be \u003c= 10000"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 1,
          "source": "annotation"
        },
        {
          "rule": "assert_le",
          "target": "field",
          "value_kind": "int",
          "int_value": 10000,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "max_event_payload_bytes",
      "type": "int32",
      "description": "max_event_payload_bytes caps how much of each tool input/output is\n stored per event. Larger payloads are truncated. Default: 32768 (32KB).",
      "default": 32768,
      "constraints": [
        "must be \u003e= 1024",
        "must be \u003c= 1048576"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 1024,
          "source": "annotation"
        },
        {
          "rule": "assert_le",
          "target": "field",
          "value_kind": "int",
          "int_value": 1048576,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "file_pattern_excludelist",
      "type": "string",
      "description": "file_pattern_excludelist is a set of glob patterns for files to\n exclude from tracking. Example: [\"*.lock\", \"node_modules/**\", \".git/**\"].",
      "repeated": true,
      "constraints": [
        "maximum size: 256 elements",
        "maximum element size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 256,
          "unit": "elements",
          "source": "annotation"
        },
        {
          "rule": "default_max_element_size",
          "target": "element",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "spool_max_bytes",
      "type": "int64",
      "description": "spool_max_bytes is the maximum spool file size in bytes. When the spool\n reaches this limit, new events are dropped until the backlog drains.\n Default: 524288000 (500MB).",
      "default": 524288000,
      "constraints": [
        "must be \u003e= 1024",
        "must be \u003c= 2147483648"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 1024,
          "source": "annotation"
        },
        {
          "rule": "assert_le",
          "target": "field",
          "value_kind": "int",
          "int_value": 2147483648,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

{
  "name": "Config",
  "package": "cavalier",
  "description": "Config is the per-profile configuration for cavalier.\n Loaded from all YAML files in ~/.cavalier/config/ and merged.\n Splitting connection and key into separate files (config.yaml + key.yaml)\n allows chmod 400 on the key file.",
  "fields": [
    {
      "name": "connection",
      "type": "message",
      "description": "connection is the gRPC connection configuration.\n Used by the identity manager for token exchange with gateway.\n Contains endpoints, private_key, and trusted_cas.",
      "required": true,
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        }
      ],
      "message": {
        "name": "Config",
        "package": "grpcconfig",
        "description": "Config is the single configuration type for all services.\n\n Bootstrap fields (endpoints, instance_id, private_key, trusted_cas) are loaded\n from YAML at boot and used to connect to the cluster.\n\n Runtime fields (ping_interval_ms, rebalance_interval_ms, listen_address,\n max_request_size, request_timeout_seconds, logger, shutdown_timeout_seconds)\n are delivered by the cluster via ServiceConfigState and can change at any time.\n\n TLS certificates are obtained automatically by the servicemanager via X509Mint\n after token exchange — they are not part of the config.",
        "fields": [
          {
            "name": "endpoints",
            "type": "message",
            "description": "Cluster endpoints. Set in bootstrap file; can be updated at runtime\n via ServiceConfigState to add/remove endpoints dynamically.",
            "repeated": true,
            "constraints": [
              "maximum size: 32 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "Host",
              "package": "host",
              "description": "Host identifies a network endpoint by hostname/IP and port.\n The host field accepts either an FQDN or an IP address (v4/v6).",
              "fields": [
                {
                  "name": "host",
                  "type": "string",
                  "description": "Hostname or IP address (e.g. \"api.example.com\" or \"10.0.0.1\").",
                  "required": true,
                  "constraints": [
                    "must be a valid hostname or IP address",
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_host",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "port",
                  "type": "int32",
                  "description": "Port number (1-65535).",
                  "constraints": [
                    "must be a valid network port (1-65535)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_net_port",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "protocol",
                  "type": "enum",
                  "description": "Transport protocol. Default TCP (zero value).",
                  "enum_values": [
                    {
                      "name": "TCP",
                      "number": 0
                    },
                    {
                      "name": "UDP",
                      "number": 1
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "instance_id",
            "type": "string",
            "description": "instance_id uniquely identifies this running instance/replica.\n Used for leader elections on boundaries with (spec.leader) = true.\n If empty, a random ID is generated at client creation time.",
            "constraints": [
              "maximum size: 128 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "private_key",
            "type": "message",
            "description": "private_key is used to mint throwaway bootstrap JWTs for the\n token exchange flow. The kid is in private_key.id;\n identity (subject/audience) comes from the delegate looked up\n by TokenExchanger using the matching kid.\n If absent, cloud-native authentication is attempted.",
            "message": {
              "name": "Key",
              "package": "key",
              "description": "Key represents a private cryptographic key (alias for ProtoKey).",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is a unique identifier for the key (corresponds to kid in JWK)",
                  "required": true,
                  "constraints": [
                    "maximum size: 256 bytes",
                    "minimum size: 1"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 256,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_min_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "base64",
                  "type": "string",
                  "description": "Base64 contains the base64url-encoded PEM private key block",
                  "required": true,
                  "constraints": [
                    "must be base64 encoded",
                    "encoding type: ENC_TYPE_KEY_PRIVATE_ANY",
                    "maximum size: 16384 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 16384,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_base64",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_enc_type",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "ENC_TYPE_KEY_PRIVATE_ANY",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "created",
                  "type": "int64",
                  "description": "Created is the Unix epoch timestamp (seconds) when the key was created\n Valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
                  "required": true,
                  "constraints": [
                    "must be \u003e= 1735689600",
                    "must be \u003c= 8045740800"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_ge",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1735689600,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_le",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8045740800,
                      "source": "annotation"
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "ping_interval_ms",
            "type": "int32",
            "description": "ping_interval_ms controls how often each endpoint is pinged for latency measurement.\n Default: 5000 (5 seconds)",
            "default": 5000
          },
          {
            "name": "rebalance_interval_ms",
            "type": "int32",
            "description": "rebalance_interval_ms controls how often the active connection is re-evaluated\n based on latency. Default: 10000 (10 seconds)",
            "default": 10000
          },
          {
            "name": "listen_address",
            "type": "message (recursive reference: host.Host)",
            "description": "listen_address is the bind address for the gRPC server. Default port 8443.",
            "required": true,
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "max_request_size",
            "type": "int64",
            "description": "max_request_size is the maximum request size in bytes.\n Must be greater than 0. Default: 10MB (10485760 bytes)",
            "default": 10485760,
            "constraints": [
              "must be \u003e 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_gt",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "request_timeout_seconds",
            "type": "int64",
            "description": "request_timeout_seconds is the timeout for client requests.\n Must be positive. Default: 30 seconds.",
            "default": 30,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ],
            "constraint_infos": [
              {
                "rule": "assert_duration",
                "target": "field",
                "value_kind": "enum",
                "enum_value": "DURATION_TYPE_POSITIVE",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "logger",
            "type": "message",
            "description": "logger configures the logger for the service.\n Controls log format (JSON/console), level, output paths, and more.",
            "message": {
              "name": "LoggerConfig",
              "package": "logger",
              "description": "LoggerConfig represents the configuration for a logger instance.\n It controls the output format, verbosity level, and formatting options.\n\n Example usage:\n   - Development mode with console output and pretty printing for local debugging\n   - Production mode with JSON output and no pretty printing for log aggregation",
              "fields": [
                {
                  "name": "name",
                  "type": "string",
                  "description": "Name is the logger name/component identifier",
                  "constraints": [
                    "maximum size: 128 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 128,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "format",
                  "type": "enum",
                  "description": "Format determines the output format for log messages (JSON or console)\n Default: FORMAT_JSON in production, FORMAT_CONSOLE in development",
                  "constraint_infos": [
                    {
                      "rule": "assert_enum_defined",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "enum_values": [
                    {
                      "name": "FORMAT_JSON",
                      "number": 1,
                      "description": "FORMAT_JSON outputs logs as JSON objects, ideal for structured logging and log aggregation systems"
                    },
                    {
                      "name": "FORMAT_CONSOLE",
                      "number": 2,
                      "description": "FORMAT_CONSOLE outputs logs in a human-readable console format, ideal for development and debugging"
                    }
                  ]
                },
                {
                  "name": "level",
                  "type": "enum",
                  "description": "Level sets the minimum severity level for log messages to be output\n Messages below this level will be filtered out\n Default: LEVEL_INFO in production, LEVEL_DEBUG in development",
                  "constraint_infos": [
                    {
                      "rule": "assert_enum_defined",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "enum_values": [
                    {
                      "name": "LEVEL_TRACE",
                      "number": 1,
                      "description": "LEVEL_TRACE is the most verbose log level, used for detailed debugging information"
                    },
                    {
                      "name": "LEVEL_DEBUG",
                      "number": 2,
                      "description": "LEVEL_DEBUG is used for debugging information, less verbose than trace"
                    },
                    {
                      "name": "LEVEL_INFO",
                      "number": 3,
                      "description": "LEVEL_INFO is used for informational messages about normal operations"
                    },
                    {
                      "name": "LEVEL_WARN",
                      "number": 4,
                      "description": "LEVEL_WARN is used for warning messages about potentially problematic situations"
                    },
                    {
                      "name": "LEVEL_ERROR",
                      "number": 5,
                      "description": "LEVEL_ERROR is used for error messages about failures and problems"
                    }
                  ]
                },
                {
                  "name": "development",
                  "type": "bool",
                  "description": "Development enables development mode which:\n   - Uses console format by default\n   - Enables stack traces for warnings and errors\n   - Uses more human-readable timestamps\n Default: false (production mode)"
                },
                {
                  "name": "pretty_print",
                  "type": "bool",
                  "description": "PrettyPrint enables pretty-printed output for JSON format\n This makes JSON logs more readable but increases output size\n Should be disabled in production for performance\n Default: false"
                },
                {
                  "name": "output_paths",
                  "type": "string",
                  "description": "OutputPaths is a list of file paths or URLs to write logs to\n Use \"stdout\" or \"stderr\" for console output\n Example: [\"stdout\", \"/var/log/app.log\"]",
                  "repeated": true,
                  "constraints": [
                    "must be a valid file path (type: PATH_ANY)",
                    "maximum size: 8 elements",
                    "maximum element size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8,
                      "unit": "elements",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_file_path",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "PATH_ANY",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_element_size",
                      "target": "element",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "error_output_paths",
                  "type": "string",
                  "description": "ErrorOutputPaths is a list of file paths or URLs to write error logs to\n Use \"stderr\" for console error output\n Example: [\"stderr\", \"/var/log/app-errors.log\"]",
                  "repeated": true,
                  "constraints": [
                    "must be a valid file path (type: PATH_ANY)",
                    "maximum size: 8 elements",
                    "maximum element size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8,
                      "unit": "elements",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_file_path",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "PATH_ANY",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_element_size",
                      "target": "element",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "disable_caller",
                  "type": "bool",
                  "description": "DisableCaller disables automatic inclusion of caller information (file:line) in log entries\n Default: false (caller information is included)"
                },
                {
                  "name": "disable_stacktrace",
                  "type": "bool",
                  "description": "DisableStacktrace disables automatic stacktraces for error-level and above log entries\n Default: false (stacktraces are included for errors)"
                },
                {
                  "name": "initial_fields",
                  "type": "map",
                  "description": "InitialFields is a map of fields to include in every log entry\n Useful for adding context like service name, version, environment, etc.\n Example: {\"service\": \"api\", \"version\": \"1.0.0\", \"environment\": \"production\"}",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 32 entries",
                    "maximum key size: 32768 bytes (default)",
                    "maximum value size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32,
                      "unit": "entries",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_key_size",
                      "target": "key",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    },
                    {
                      "rule": "default_max_value_size",
                      "target": "value",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ],
                  "map_key_type": "string",
                  "map_value_type": "string"
                }
              ]
            }
          },
          {
            "name": "shutdown_timeout_seconds",
            "type": "int64",
            "description": "shutdown_timeout_seconds is the maximum time (in seconds) to wait for graceful\n shutdown after SIGTERM before forcing immediate shutdown.\n Must be positive. Default: 30 seconds.",
            "default": 30,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ],
            "constraint_infos": [
              {
                "rule": "assert_duration",
                "target": "field",
                "value_kind": "enum",
                "enum_value": "DURATION_TYPE_POSITIVE",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "max_concurrent_streams",
            "type": "int32",
            "description": "max_concurrent_streams limits the number of concurrent gRPC streams per connection.\n Prevents resource exhaustion from clients opening unlimited streams.\n Default: 100. Set to 0 to use the gRPC library default (unlimited).",
            "default": 100
          },
          {
            "name": "max_send_msg_size",
            "type": "int64",
            "description": "max_send_msg_size is the maximum response message size in bytes.\n Prevents the server from sending responses that could OOM clients.\n Default: 16MB (16777216 bytes). Set to 0 to use the gRPC library default.",
            "default": 16777216
          },
          {
            "name": "keepalive_min_time_seconds",
            "type": "int64",
            "description": "keepalive_min_time_seconds is the minimum interval clients must wait between\n keepalive pings. Clients pinging more frequently are disconnected.\n Default: 30 seconds. Set to 0 to disable enforcement.",
            "default": 30
          },
          {
            "name": "trusted_cas",
            "type": "message",
            "description": "trusted_cas is the explicit list of CA certificates trusted for SPIFFE TLS\n verification when connecting to cluster endpoints. It must not be empty.",
            "repeated": true,
            "constraints": [
              "maximum size: 32 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "X509Cert",
              "package": "x509",
              "description": "ProtoCert represents an X.509 certificate.\n The certificate is stored as a base64-encoded PEM block.\n Use NewProtoCert() in Go with DER-encoded certificate bytes to create.",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is a unique identifier for the certificate",
                  "constraints": [
                    "maximum size: 256 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 256,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "base64",
