  "name": "TenantConfig",
  "package": "tenant_config",
  "description": "TenantConfig aggregates per-service tenant configuration slices.\n Field names match service names; field numbers are stable via registry.yaml.",
  "fields": [
    {
      "name": "kernel",
      "type": "message",
      "message": {
        "name": "KernelTenantConfig",
        "package": "credentials",
        "description": "KernelTenantConfig is the per-tenant kernel configuration slice.\n Tacplus auto-generates TenantConfig with this as the kernel field.",
        "fields": [
          {
            "name": "cred_pairs",
            "type": "message",
            "description": "cred_pairs are the tenant's cred_pairs (JWK + entitlements + tenant-relative\n namespaces). They authenticate management RPCs as ordinary C2S identities\n (no P2S). Public keys only — private keys never enter the cluster. The\n creating root registers the tenant's first cred_pair public key via\n kernel.TenantAdmin.SetTenantConfig (bootstrap); nothing is minted or\n delivered server-side. Holders generate their own keypairs off-cluster.",
            "repeated": true,
            "constraints": [
              "maximum size: 256 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "elements",
                "source": "annotation"
