            ],
            "message": {
              "name": "CredPair",
              "package": "credentials",
              "description": "CredPair is a tenant-scoped credential. Public key stored in the tenant's\n KernelTenantConfig slice; private key never leaves the holder. Used to\n authenticate kernel.TenantAdmin RPCs and (downstream) any tenant-scoped\n RPC across the cluster.\n\n A request authenticated by CredPair carries the SPIFFE URI\n `spiffe://\u003cspiffe_prefix\u003e/\u003ctenant_name\u003e/users/cred-pair:\u003cid\u003e`.\n\n `entitlements` must always be a subset of the tenant's ceiling\n (kernel.Constraints.entitlements_ceiling). Enforcement is in\n kernel.TenantAdmin.SetTenantConfig.",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "id is a unique identifier for this cred_pair within its owning tenant.",
                  "required": true,
