{
  "name": "Config",
  "package": "eventbus",
  "description": "Config for the event-bus service. Stored in kernel via grpc_config.\n At boot, eventbus connects to kernel to fetch this config, then merges\n with env vars (env takes precedence via PROTO_CONFIG_* env var mappings).",
  "fields": [
    {
      "name": "node_role",
      "type": "enum",
      "description": "node_role determines the embedded Kafka (KRaft) process role.",
      "constraint_infos": [
        {
          "rule": "assert_enum_defined",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
