      ],
      "enum_values": [
        {
          "name": "KAFKA_ROLE_COMBINED",
          "number": 1,
          "description": "KAFKA_ROLE_COMBINED: runs both broker and controller in one process.\n Simplest deployment for small clusters (3-5 nodes)."
        },
        {
          "name": "KAFKA_ROLE_BROKER",
          "number": 2,
          "description": "KAFKA_ROLE_BROKER: data-only node. Stores partitions, serves producers\n and consumers. Scales horizontally."
        },
        {
          "name": "KAFKA_ROLE_CONTROLLER",
          "number": 3,
          "description": "KAFKA_ROLE_CONTROLLER: metadata quorum only. Runs the KRaft consensus\n protocol for leader election and partition assignment.\n Deploy an odd number (3 or 5) for quorum."
        }
      ]
    },
    {
      "name": "data_dir",
      "type": "string",
      "description": "data_dir is the Kafka log/data directory.",
