{
  "name": "SubscribeRequest",
  "package": "eventbus",
  "description": "SubscribeRequest is sent on the bidi stream to control replay.\n The first message establishes the session; subsequent messages adjust\n position, speed, pause state, or backpressure without closing the stream.\n\n Every field is applied as-is — the server replaces its current state\n with the full contents of each new SubscribeRequest. To change only\n the speed, the client re-sends the same seek + the new speed.",
  "fields": [
    {
      "name": "offset",
      "type": "int64",
      "oneof": true,
      "oneof_name": "start_from",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "timestamp",
      "type": "message",
      "oneof": true,
      "oneof_name": "start_from"
    },
    {
      "name": "latest",
      "type": "bool",
      "oneof": true,
      "oneof_name": "start_from"
    },
    {
      "name": "earliest",
      "type": "bool",
      "oneof": true,
      "oneof_name": "start_from"
    },
    {
      "name": "consumer_group",
      "type": "string",
      "description": "Consumer group for offset tracking. Only read from the first message;\n ignored on subsequent resubscribes (consumer group is immutable per session).",
      "constraints": [
        "maximum size: 256 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 256,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "speed_multiplier",
      "type": "double",
      "description": "speed_multiplier controls replay pacing relative to original event timestamps.\n 0 = max throughput (catch-up mode, no delay between events).\n 1.0 = real-time (events delivered at the same rate they were produced).\n 10.0 = 10x fast-forward.\n Can be changed mid-stream without seeking.",
      "constraints": [
        "must be \u003e= 0.000000",
        "must be \u003c= 1000.000000"
      ],
      "constraint_infos": [
        {
          "rule": "assert_float",
          "target": "field",
          "value_kind": "float",
          "float_value": 0,
          "operator": "ge",
          "source": "annotation"
        },
        {
          "rule": "assert_float",
          "target": "field",
          "value_kind": "float",
          "float_value": 1000,
          "operator": "le",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "pause",
      "type": "bool",
      "description": "pause stops delivery without closing the stream or releasing the consumer.\n The server holds its position. Send pause=false (or a new seek) to resume."
    },
    {
      "name": "backpressure",
      "type": "enum",
      "description": "backpressure tells the server what to do when the client is slow.",
      "constraint_infos": [
        {
          "rule": "assert_enum_defined",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        }
      ],
      "enum_values": [
        {
          "name": "BACKPRESSURE_BUFFER",
          "number": 0,
          "description": "BACKPRESSURE_BUFFER: server buffers events until the client catches up.\n Default gRPC behaviour. Safe but risks unbounded memory if the client\n falls behind permanently."
        },
        {
          "name": "BACKPRESSURE_DROP_OLD",
          "number": 1,
          "description": "BACKPRESSURE_DROP_OLD: server skips ahead to the latest available offset,\n discarding events the client couldn't consume in time. The client sees\n a gap but never falls behind."
        },
        {
          "name": "BACKPRESSURE_SAMPLE",
          "number": 2,
          "description": "BACKPRESSURE_SAMPLE: server delivers every Nth event (N = sample_interval),\n dropping the rest. Useful for dashboards that need shape, not completeness."
        }
      ]
    },
    {
      "name": "sample_interval",
      "type": "int32",
      "description": "sample_interval: when backpressure=BACKPRESSURE_SAMPLE, deliver every\n Nth event and drop the rest. Ignored for other policies.",
      "default": 1,
      "constraints": [
        "must be \u003e= 1",
        "must be \u003c= 10000"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 1,
          "source": "annotation"
        },
        {
          "rule": "assert_le",
          "target": "field",
          "value_kind": "int",
          "int_value": 10000,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "partitions",
      "type": "int32",
      "description": "partitions restricts consumption to specific partition IDs.\n Empty = subscribe to all partitions (default, uses consumer-group rebalancing).\n When set, uses manual assignment (no rebalancing).",
