      }
    },
    {
      "name": "delegates",
      "type": "message",
      "description": "delegates hold credentials for services that can request tokens.\n Each delegate identifies a service and its authorized target services.",
      "repeated": true,
      "constraints": [
        "maximum size: 128 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 128,
          "unit": "elements",
          "source": "annotation"
        }
      ],
      "message": {
        "name": "Delegate",
        "package": "kernel",
        "description": "Delegate holds bootstrap matchers for a service or machine client that can request tokens.\n Each delegate is identified by name, which becomes the service path segment in\n the issued token's SPIFFE URI:\n spiffe://\u003ctrust-domain\u003e/system/\u003clocation\u003e/services/\u003cdelegate_name\u003e.\n Authenticates via a projected Kubernetes service-account token or cloud identity.\n\n Two authorization models:\n   - S2S (identity-only): tokens carry only the SPIFFE URI as sub.\n     Receiving services enforce access via auth_services RE2 patterns\n     that match against the caller's service path.\n   - C2S (entitlement-based): OPA returns TokenEntitlements directly.\n     Kernel embeds expanded per-service RPC lists in the user token.",
        "fields": [
          {
            "name": "name",
            "type": "string",
            "description": "name is the delegate's identity — becomes the final service path segment in\n the SPIFFE URI. For workload children: parent/\u003cchild\u003e.",
            "required": true,
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "cloud_identities",
            "type": "message",
            "repeated": true,
            "constraints": [
              "maximum size: 8 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 8,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "CloudIdentityMatcher",
              "package": "kernel",
              "description": "CloudIdentityMatcher configures which cloud identities a delegate accepts.\n The delegate proves identity using a CloudIdentityProof; this config\n tells kernel what to expect.",
              "fields": [
                {
                  "name": "vendor",
                  "type": "enum",
                  "description": "vendor identifies the cloud provider.",
                  "constraint_infos": [
                    {
                      "rule": "assert_enum_defined",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "enum_values": [
                    {
                      "name": "CLOUD_VENDOR_AWS",
                      "number": 1,
                      "description": "Amazon Web Services (AWS)"
                    },
                    {
                      "name": "CLOUD_VENDOR_AZURE",
                      "number": 2,
                      "description": "Microsoft Azure"
                    },
                    {
                      "name": "CLOUD_VENDOR_GCP",
                      "number": 3,
                      "description": "Google Cloud Platform (GCP)"
                    },
                    {
                      "name": "CLOUD_VENDOR_ORACLE",
                      "number": 4,
                      "description": "Oracle Cloud"
                    },
                    {
                      "name": "CLOUD_VENDOR_ALIBABA",
                      "number": 5,
                      "description": "Alibaba Cloud"
                    },
                    {
                      "name": "CLOUD_VENDOR_IBM",
                      "number": 6,
                      "description": "IBM Cloud"
                    }
                  ]
                },
                {
                  "name": "expected_identity",
                  "type": "string",
                  "description": "expected_identity is the cloud identity to match against.\n AWS: IAM role ARN. GCP: service account email. Azure: managed identity client ID.",
                  "required": true,
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "kubernetes_service_accounts",
            "type": "message",
            "description": "kubernetes_service_accounts lists the Kubernetes (namespace, service\n account) pairs that authenticate as this delegate via a projected SA\n token.",
            "repeated": true,
            "constraints": [
              "maximum size: 8 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 8,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "KubernetesServiceAccountMatcher",
              "package": "kernel",
              "description": "KubernetesServiceAccountMatcher configures which Kubernetes service accounts\n a delegate accepts. The workload proves identity with a projected\n service-account token; this config tells kernel which (namespace, service\n account) pairs map to this delegate. Repeated on Delegate so multiple SAs\n (multi-namespace / migration) can map to one delegate.",
              "fields": [
                {
                  "name": "kubernetes_namespace",
                  "type": "string",
                  "description": "kubernetes_namespace is the Kubernetes namespace of the service account.\n Named explicitly to avoid collision with the Cavalier tenant namespace\n concept — this is the K8s namespace, not an authorization namespace.",
                  "required": true,
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "kubernetes_service_account",
                  "type": "string",
                  "description": "kubernetes_service_account is the Kubernetes ServiceAccount name.",
                  "required": true,
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "authorized_services",
            "type": "enum",
            "description": "authorized_services lists services this delegate can request tokens for.\n Values are generated ServiceName enum entries matching service declarations.\n The delegate can always request a token for itself (sub=name).\n Use SERVICE_NAME_ANY to allow all services.",
            "repeated": true,
            "constraints": [
              "maximum size: 64 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "enum_values": [
              {
                "name": "SERVICE_NAME_SENTINEL",
                "number": 5
              },
              {
                "name": "SERVICE_NAME_GATEWAY",
                "number": 7
              },
              {
                "name": "SERVICE_NAME_KERNEL",
                "number": 8
              },
              {
                "name": "SERVICE_NAME_LETSENCRYPT",
                "number": 9
              },
              {
                "name": "SERVICE_NAME_GRAPHDB",
                "number": 13
              },
              {
                "name": "SERVICE_NAME_EVENTBUS",
                "number": 18
              },
              {
                "name": "SERVICE_NAME_TIMEDB",
                "number": 20
              },
              {
                "name": "SERVICE_NAME_OAUTH",
                "number": 21
              },
              {
                "name": "SERVICE_NAME_MSGGATEWAY",
                "number": 28
              },
              {
                "name": "SERVICE_NAME_OPA",
                "number": 29
              },
              {
                "name": "SERVICE_NAME_STRATUM",
                "number": 34
              },
              {
                "name": "SERVICE_NAME_ARGUS",
                "number": 35
              },
              {
                "name": "SERVICE_NAME_KMAKER",
                "number": 49
              },
              {
                "name": "SERVICE_NAME_SAMLSVC",
                "number": 50
              },
              {
                "name": "SERVICE_NAME_ANY",
                "number": 99
              }
            ]
          },
          {
            "name": "custom_claims",
            "type": "map",
            "description": "custom_claims are static key-value pairs added to every access token\n minted for this delegate. Useful for identity claims (e.g. email).\n Standard JWT claims (sub, iss, aud, exp, iat, azp, nbf, jti, typ,\n parent_sub) are reserved and will be skipped.",
            "repeated": true,
            "constraints": [
              "maximum size: 20 entries",
              "maximum key size: 32768 bytes (default)",
              "maximum value size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 20,
                "unit": "entries",
                "source": "annotation"
              },
              {
                "rule": "default_max_key_size",
                "target": "key",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              },
              {
                "rule": "default_max_value_size",
                "target": "value",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ],
            "map_key_type": "string",
            "map_value_type": "string"
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "fqdn",
      "type": "string",
      "description": "fqdn is the fully qualified domain name for this cluster\n (e.g. \"api.example.com\"). Published to Identity state for\n services like letsencrypt. No default — must be set for production.",
      "constraints": [
        "must be a fully qualified domain name",
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_fqdn",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "issuer",
      "type": "string",
      "description": "issuer is the full issuer URL for tokens minted by this cluster.\n For local development, computed as https://\u003cfqdn\u003e:\u003cport\u003e (port omitted if 443).\n For production behind a load balancer, set explicitly (e.g. \"https://api.example.com\").",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "key_rotation_interval_seconds",
      "type": "int64",
      "description": "key_rotation_interval_seconds is how often the exchanger rotates\n its own signing keys. Default: 24 hours.",
      "default": 86400
    },
    {
      "name": "default_token_expiry_seconds",
      "type": "int64",
      "description": "default_token_expiry_seconds is the default lifetime for issued\n access tokens when the request does not specify an expiry. Default: 1 hour.",
      "default": 3600
    },
    {
      "name": "ca_cert_lifetime_seconds",
      "type": "int64",
      "description": "ca_cert_lifetime_seconds is the lifetime for node CA certificates.\n Default: 31536000 (1 year). Node CA certs are regenerated on restart.",
      "default": 31536000,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "access_token_lifetime_seconds",
      "type": "int64",
      "description": "access_token_lifetime_seconds is the default lifetime for user access tokens\n minted via MintToken. Default: 900 (15 minutes).",
      "default": 900,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "refresh_token_lifetime_seconds",
      "type": "int64",
      "description": "refresh_token_lifetime_seconds is the default lifetime for user refresh tokens\n minted via MintToken. Default: 86400 (24 hours).",
      "default": 86400,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "tls_cert_lifetime_seconds",
      "type": "int64",
      "description": "tls_cert_lifetime_seconds is the lifetime for auto-TLS service certificates.\n Kernel sends a renewal request at half-life. Default: 86400 (24 hours).",
      "default": 86400,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "max_token_lifetime_seconds",
      "type": "int64",
      "description": "max_token_lifetime_seconds is the maximum lifetime kernel will allow for\n any minted token. Requests with exp beyond now + this value are rejected.\n Delegates control their own exp policy within this ceiling.\n Default: 2592000 (30 days).",
      "default": 2592000,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "offline_token_lifetime_seconds",
      "type": "int64",
      "description": "offline_token_lifetime_seconds is the default lifetime for Offline Tokens\n (OT) — the long-lived, identity-only tokens persisted on disk by the\n cavalier daemon and renewed before half-life. Months, not hours.\n Default: 7776000 (90 days). Exempt from max_token_lifetime_seconds, which\n caps short-lived access/service tokens.",
      "default": 7776000,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "root_cred_pairs",
      "type": "message (recursive reference: credentials.CredPair)",
      "description": "root_cred_pairs are the bootstrap admin credentials, rendered into this\n config by the operator from operator.yaml. Each is an ordinary C2S CredPair\n owned by the root namespace; kernel installs them into the root namespace's\n TenantConfig at boot (granting full entitlements) so a holder can sign a\n proof, exchange it via MintClientToken, and provision tenants/projects via\n TenantAdmin. Only the public half is carried here.",
      "repeated": true,
      "constraints": [
        "maximum size: 64 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "elements",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "spiffe_trust_domain",
      "type": "string",
      "description": "spiffe_trust_domain is the SPIFFE URI authority: a globally unique instance\n name for this autonomous-system instance (need not be a DNS domain). It must\n not contain '/', a scheme, query, or fragment, and carries no path. Service\n identity is built by the generated sys/spiffe helper as:\n   spiffe://\u003cspiffe_trust_domain\u003e/system/\u003clocation_path...\u003e/services/\u003cservice_label\u003e\n If empty, SPIFFE IDs are not set on issued tokens or X509 URI SANs. Kernel\n copies this (with location_path) into the runtime grpcconfig.Config it seeds\n into ServiceConfigState, so every service shares one trust domain.",
      "default": "local.dev",
      "constraints": [
        "maximum size: 256 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 256,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "location_path",
      "type": "string",
      "description": "location_path is this deployment's topology path under /system — opaque,\n tag-delimited, slash-separated segments, arity not fixed (e.g.\n \"aws/123456789012/us-east-1a/cluster-7/team-a\"). Segments follow the SPIFFE\n segment grammar and must not be reserved tags. Supplied by the operator from\n runtime config (where the cluster runs); it is not a token claim. May be\n empty (no topology tiers).",
      "constraints": [
        "maximum size: 256 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 256,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "health_probe_port",
      "type": "int32",
      "description": "health_probe_port is the plaintext gRPC port for k8s health probes.\n Kernel's hand-written bootstrap bypasses the generated ServiceManager,\n so this field must be on Kernel.Config (not only on Grpcconfig.Config).\n Default matches the platform-wide health probe port.",
      "default": 8444
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

fields.description:
InitialFields is a map of fields to include in every log entry
 Useful for adding context like service name, version, environment, etc.
 Example: {"service": "api", "version": "1.0.0", "environment": "production"}

types.schema_json:
{
  "name": "ConfigState",
  "package": "kernel",
  "description": "ConfigState is the kernel-hosted persistence boundary for tenants/projects.\n Kernel writes it and persists it; other services watch their per-tenant/\n per-project config slice via the export: true wire.",
  "fields": [
    {
      "name": "tenants",
      "type": "message",
      "description": "tenants is the list of all tenant records, keyed by tenant.name.",
      "repeated": true,
      "constraints": [
        "maximum size: 4096 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 4096,
          "unit": "elements",
          "source": "annotation"
        }
      ],
      "message": {
        "name": "Tenant",
        "package": "kernel",
        "description": "Tenant is the core identity record for a tenant in the cluster.\n `name` is unique, immutable, and becomes the tenant's SPIFFE segment:\n   spiffe://\u003ctrust-domain\u003e/tenants/\u003cname\u003e/...",
        "fields": [
          {
            "name": "name",
            "type": "string",
            "required": true,
            "constraints": [
              "maximum size: 128 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "status",
            "type": "enum",
            "enum_values": [
              {
                "name": "TENANT_STATUS_ACTIVE",
                "number": 1
              },
              {
                "name": "TENANT_STATUS_SUSPENDED",
                "number": 2
              }
            ]
          },
          {
            "name": "constraints",
            "type": "message",
            "description": "constraints is the ancestor-set limits (entitlements ceiling now; domain\n later). Set at creation; mutable only by an ancestor.",
            "message": {
              "name": "Constraints",
              "package": "kernel",
              "description": "Constraints are the limits an ancestor places on a tenant. They live on the\n Tenant record (set at CreateTenant), are mutable only by an ancestor, and are\n immutable to the tenant itself — so the tenant genuinely cannot raise its own\n limits. Validated on CreateTenant and SetTenantConfig.\n\n (The \"min-admin-credential\" rule — config must always contain \u003e=1 cred_pair\n entitled to administer the tenant — is NOT a field here: it is an always-on\n invariant enforced in the SetTenantConfig validation path, satisfiable by\n create-and-discard. It is not an ancestor toggle.)",
              "fields": [
                {
                  "name": "entitlements_ceiling",
                  "type": "message",
