{
  "name": "KernelDiskState",
  "package": "kernel",
  "description": "============================================================================\n Kernel disk persistence (UC1 whole-state snapshot)\n ============================================================================\n\n KernelDiskState is kernel's OWN durable state, snapshotted to kernel's local\n volume via the tacplus diskstore. It is a service_store with NO store_key,\n so tacplus generates UC1 snapshot save/load only (no distributed key-value\n service, no redo log) — kernel persists its whole (small) state as one\n atomic object and restores it on boot.\n\n Kernel persists ONLY its own state — never another service's. Ephemeral,\n rebuilt-at-runtime state (Cluster membership, ServiceHealth, Identity.fqdn,\n WorkloadState.localities, TrustedCa from Config) is deliberately NOT\n snapshotted; only state that must survive a restart is.",
  "fields": [
    {
      "name": "signing_keys",
      "type": "message",
      "description": "signing_keys are the active private signing keys, one per algorithm\n (EdDSA for internal tokens, ES256 for WIF external tokens). Each record\n pairs the private key with its public JWK.",
      "repeated": true,
      "constraints": [
        "maximum size: 8 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 8,
          "unit": "elements",
          "source": "annotation"
        }
      ],
      "message": {
        "name": "SigningKeyRecord",
        "package": "kernel",
        "description": "SigningKeyRecord pairs a private signing key with its public JWK so the key\n can be fully restored on restart without re-derivation. Carried inside\n KernelDiskState (the UC1 disk snapshot), one record per active algorithm\n (EdDSA / ES256).",
        "fields": [
          {
            "name": "key",
            "type": "message",
            "message": {
              "name": "Key",
              "package": "key",
              "description": "Key represents a private cryptographic key (alias for ProtoKey).",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is a unique identifier for the key (corresponds to kid in JWK)",
                  "required": true,
                  "constraints": [
                    "maximum size: 256 bytes",
                    "minimum size: 1"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
