              "package": "kernel",
              "description": "Constraints are the limits an ancestor places on a tenant. They live on the\n Tenant record (set at CreateTenant), are mutable only by an ancestor, and are\n immutable to the tenant itself — so the tenant genuinely cannot raise its own\n limits. Validated on CreateTenant and SetTenantConfig.\n\n (The \"min-admin-credential\" rule — config must always contain \u003e=1 cred_pair\n entitled to administer the tenant — is NOT a field here: it is an always-on\n invariant enforced in the SetTenantConfig validation path, satisfiable by\n create-and-discard. It is not an ancestor toggle.)",
              "fields": [
                {
                  "name": "entitlements_ceiling",
                  "type": "message",
                  "description": "entitlements_ceiling is the maximum set of entitlements anyone inside this\n tenant may ever hold. Every cred_pair's entitlements ⊆ this; a sub-tenant's\n ceiling ⊆ this. Replaces the former standalone Tenant.entitlements field.",
                  "message": {
                    "name": "TokenEntitlements",
                    "package": "entitlements",
                    "description": "TokenEntitlements holds compressed C2S entitlements embedded in user tokens.\n OPA returns this structure directly; the token authority embeds it in the JWT service_entitlements claim.\n grants may contain exact or wildcard grant tokens; generated helpers normalize them before authorization.",
                    "fields": [
                      {
                        "name": "grants",
                        "type": "string",
                        "description": "grants is a flat list of generated grant tokens, e.g. PACKAGE_SERVICE_RPC.",
