                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 16384,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_base64",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_enc_type",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "ENC_TYPE_KEY_PRIVATE_ANY",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "created",
                  "type": "int64",
                  "description": "Created is the Unix epoch timestamp (seconds) when the key was created\n Valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
                  "required": true,
                  "constraints": [
                    "must be \u003e= 1735689600",
                    "must be \u003c= 8045740800"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_ge",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1735689600,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_le",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8045740800,
                      "source": "annotation"
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "id",
            "type": "string",
            "description": "Id is an optional stable key for chain collections.",
            "constraints": [
              "maximum size: 256 bytes"
            ],
