{
  "name": "KmakerConfigState",
  "package": "kmaker",
  "description": "KmakerConfigState is the state boundary for kmaker service configuration.\n Auto-injected by tacplus from (spec.grpc_config) annotation.",
  "fields": [
    {
      "name": "config",
      "type": "message",
      "message": {
        "name": "Config",
        "package": "kmaker",
        "description": "Config is rendered by operator and mounted into kmaker at startup.",
        "fields": [
          {
            "name": "cluster_name",
            "type": "string",
            "description": "cluster_name is the logical Cavalier cluster this kmaker signs for.",
            "required": true,
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
