            "message": {
              "name": "Host",
              "package": "host",
              "description": "Host identifies a network endpoint by hostname/IP and port.\n The host field accepts either an FQDN or an IP address (v4/v6).",
              "fields": [
                {
                  "name": "host",
                  "type": "string",
                  "description": "Hostname or IP address (e.g. \"api.example.com\" or \"10.0.0.1\").",
                  "required": true,
                  "constraints": [
                    "must be a valid hostname or IP address",
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_host",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "port",
