                  "required": true,
                  "constraints": [
                    "maximum size: 128 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 128,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "kernel_cert_lifetime_seconds",
            "type": "int64",
            "description": "kernel_cert_lifetime_seconds caps issued kernel certificate lifetimes.",
            "default": 86400,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ],
            "constraint_infos": [
              {
                "rule": "assert_duration",
                "target": "field",
                "value_kind": "enum",
                "enum_value": "DURATION_TYPE_POSITIVE",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "tls",
            "type": "message (recursive reference: x509.X509CertChain)",
            "description": "tls is the optional serving certificate for kmaker's own gRPC listener.\n When unset, kmaker starts without transport TLS for local/dev only."
          },
          {
            "name": "health_probe_port",
            "type": "int32",
            "description": "health_probe_port is the plaintext gRPC port for k8s health probes.\n Kmaker's hand-written bootstrap bypasses the generated ServiceManager,\n so this field must be on Kmaker.Config (not only on Grpcconfig.Config).\n Default matches the platform-wide health probe port.",
            "default": 8444
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

fields.description:
InitialFields is a map of fields to include in every log entry
 Useful for adding context like service name, version, environment, etc.
 Example: {"service": "api", "version": "1.0.0", "environment": "production"}

types.schema_json:
{
  "name": "MapEmpty",
  "package": "operator",
  "fields": [
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

{
  "name": "OperatorConfigState",
  "package": "operator",
  "description": "OperatorConfigState is the state boundary for operator service configuration.\n Auto-injected by tacplus from (spec.grpc_config) annotation.",
  "fields": [
    {
      "name": "config",
      "type": "message",
      "message": {
        "name": "Config",
        "package": "operator",
        "description": "OperatorConfig is the top-level operator configuration.\n\n Lifecycle:\n   1. operator init ca                   — generate root CA → crypto.yaml\n   2. operator init cluster --ca \u003cpath\u003e  — generate cluster PKI + write operator.yaml\n   3. operator                           — run (IN_CLUSTER) or generate charts (GENERATE_ONLY)\n\n When deployed to Kubernetes:\n   operator.yaml  → ConfigMap  (cavalier-operator-config)\n   crypto.yaml    → Secret     (cavalier-operator-crypto)\n Both are mounted and merged by the operator at startup.",
        "fields": [
          {
            "name": "mode",
            "type": "enum",
            "description": "How the operator runs.",
            "enum_values": [
              {
                "name": "IN_CLUSTER",
                "number": 0,
                "description": "IN_CLUSTER is the default: the operator runs inside Kubernetes and\n continuously reconciles the desired cluster state by managing Helm releases.\n gateway_nodes is automatically set to the number of schedulable nodes."
              },
              {
                "name": "GENERATE_ONLY",
                "number": 1,
                "description": "GENERATE_ONLY: one-shot CLI mode. Generates Helm charts, writes them to\n output_dir, and exits. Does not communicate with the Kubernetes API."
              }
            ]
          },
          {
            "name": "fqdn",
            "type": "string",
            "description": "Public FQDN for the cluster (e.g. \"api.example.com\").",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "port",
            "type": "int32",
            "description": "HTTPS gateway port. Default 443 for production; 8443 for local testing.",
            "default": 443
          },
          {
            "name": "namespace",
            "type": "string",
            "description": "Kubernetes namespace to deploy all cavalier services into.",
            "default": "cavalier",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "topology",
            "type": "message",
            "description": "Service replica topology.",
            "message": {
              "name": "Topology",
              "package": "operator",
              "description": "Topology declares the desired replica count for each service.\n\n gateway_nodes is special: when set to 0 and mode = IN_CLUSTER, the operator\n automatically sets it to the number of schedulable Kubernetes nodes at each\n reconciliation cycle (one gateway per node). When mode = GENERATE_ONLY,\n gateway_nodes must be set explicitly.\n\n msggateway_nodes is on hold; leave at 0 to disable.",
              "fields": [
                {
                  "name": "kernel_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "sentinel_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "eventbus_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "gateway_nodes",
                  "type": "int32",
                  "description": "Set to 0 to auto-derive from schedulable node count (IN_CLUSTER only).\n When enabled proxy services (anthropic, openai, gitlab, github) also\n scale to one replica per gateway node."
                },
                {
                  "name": "oauth_nodes",
                  "type": "int32",
                  "description": "oauth_nodes is used when optional_services.oauth = true (default).",
                  "default": 3
                },
                {
                  "name": "msggateway_nodes",
                  "type": "int32",
                  "description": "On hold — leave at 0 to disable."
                },
                {
                  "name": "opa_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "timedb_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "graphdb_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "argus_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "stratum_nodes",
                  "type": "int32",
                  "default": 3
                },
                {
                  "name": "saml_nodes",
                  "type": "int32",
                  "description": "saml_nodes is used when optional_services.saml = true.",
                  "default": 3
                },
                {
                  "name": "kmaker_nodes",
                  "type": "int32",
                  "description": "kmaker_nodes is the number of bootstrap certificate authority replicas.\n Kernel instances contact kmaker with Kubernetes projected service account\n tokens to obtain kernel certificates before kernel itself is available.",
                  "default": 3
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "tls",
            "type": "message",
            "description": "TLS configuration — letsencrypt or custom CA.\n Validation: if tls.letsencrypt = false, tls.ca must be set.",
            "message": {
              "name": "TLSConfig",
              "package": "operator",
              "description": "TLSConfig controls how edge-facing TLS certificates are obtained.\n When letsencrypt = true, the operator deploys one letsencrypt service replica.",
              "fields": [
                {
                  "name": "letsencrypt",
                  "type": "bool",
                  "description": "When true, Let's Encrypt is used for edge TLS and one letsencrypt service\n replica is deployed. The gateway must be reachable on port 443 from the\n public internet.\n When false, ca must be populated with a valid CA chain."
                },
                {
                  "name": "ca",
                  "type": "message",
                  "description": "Custom CA chain for edge TLS certificates.\n Required when letsencrypt = false. Ignored when letsencrypt = true.",
                  "message": {
                    "name": "X509CertChain",
                    "package": "x509",
                    "description": "X509CertChain contains a certificate chain and optional private key.\n chain[0] is the leaf (end-entity) cert, followed by intermediates, ordered toward root.\n When key is present, the chain is a full credential suitable for TLS.",
                    "fields": [
                      {
                        "name": "chain",
                        "type": "message",
                        "description": "chain[0] is the leaf (end-entity) cert, followed by intermediates, ordered toward root.",
                        "repeated": true,
                        "constraints": [
                          "maximum size: 8 elements",
                          "minimum size: 1"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 8,
                            "unit": "elements",
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_min_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1,
                            "unit": "elements",
                            "source": "annotation"
                          }
                        ],
                        "message": {
                          "name": "X509Cert",
                          "package": "x509",
                          "description": "ProtoCert represents an X.509 certificate.\n The certificate is stored as a base64-encoded PEM block.\n Use NewProtoCert() in Go with DER-encoded certificate bytes to create.",
                          "fields": [
                            {
                              "name": "id",
                              "type": "string",
                              "description": "Id is a unique identifier for the certificate",
                              "constraints": [
                                "maximum size: 256 bytes"
                              ],
                              "constraint_infos": [
                                {
                                  "rule": "assert_max_size",
                                  "target": "field",
                                  "value_kind": "int",
                                  "int_value": 256,
                                  "unit": "bytes",
                                  "source": "annotation"
                                }
                              ]
                            },
                            {
                              "name": "base64",
                              "type": "string",
                              "description": "Base64 contains the base64url-encoded PEM certificate block",
                              "required": true,
                              "constraints": [
                                "must be base64 encoded",
                                "maximum size: 16384 bytes"
                              ],
                              "constraint_infos": [
                                {
                                  "rule": "assert_required",
                                  "target": "field",
                                  "value_kind": "bool",
                                  "bool_value": true,
                                  "source": "annotation"
                                },
                                {
                                  "rule": "assert_max_size",
                                  "target": "field",
                                  "value_kind": "int",
                                  "int_value": 16384,
                                  "unit": "bytes",
                                  "source": "annotation"
                                },
                                {
                                  "rule": "assert_base64",
                                  "target": "field",
                                  "value_kind": "bool",
                                  "bool_value": true,
                                  "source": "annotation"
                                }
                              ]
                            }
                          ]
                        }
                      },
                      {
                        "name": "key",
                        "type": "message",
                        "description": "optional private key for the leaf cert; present when chain is a full credential.",
                        "message": {
                          "name": "Key",
                          "package": "key",
                          "description": "Key represents a private cryptographic key (alias for ProtoKey).",
                          "fields": [
                            {
                              "name": "id",
                              "type": "string",
                              "description": "Id is a unique identifier for the key (corresponds to kid in JWK)",
                              "required": true,
                              "constraints": [
                                "maximum size: 256 bytes",
                                "minimum size: 1"
                              ],
                              "constraint_infos": [
                                {
                                  "rule": "assert_required",
                                  "target": "field",
                                  "value_kind": "bool",
                                  "bool_value": true,
                                  "source": "annotation"
                                },
                                {
                                  "rule": "assert_max_size",
                                  "target": "field",
                                  "value_kind": "int",
                                  "int_value": 256,
                                  "unit": "bytes",
                                  "source": "annotation"
                                },
                                {
                                  "rule": "assert_min_size",
                                  "target": "field",
                                  "value_kind": "int",
                                  "int_value": 1,
                                  "unit": "bytes",
                                  "source": "annotation"
                                }
                              ]
                            },
                            {
                              "name": "base64",
                              "type": "string",
                              "description": "Base64 contains the base64url-encoded PEM private key block",
                              "required": true,
                              "constraints": [
                                "must be base64 encoded",
                                "encoding type: ENC_TYPE_KEY_PRIVATE_ANY",
                                "maximum size: 16384 bytes"
                              ],
                              "constraint_infos": [
                                {
                                  "rule": "assert_required",
                                  "target": "field",
                                  "value_kind": "bool",
                                  "bool_value": true,
                                  "source": "annotation"
                                },
                                {
                                  "rule": "assert_max_size",
                                  "target": "field",
                                  "value_kind": "int",
                                  "int_value": 16384,
                                  "unit": "bytes",
                                  "source": "annotation"
                                },
                                {
                                  "rule": "assert_base64",
                                  "target": "field",
                                  "value_kind": "bool",
                                  "bool_value": true,
                                  "source": "annotation"
                                },
                                {
                                  "rule": "assert_enc_type",
                                  "target": "field",
                                  "value_kind": "enum",
                                  "enum_value": "ENC_TYPE_KEY_PRIVATE_ANY",
                                  "source": "annotation"
                                }
                              ]
                            },
                            {
                              "name": "created",
                              "type": "int64",
                              "description": "Created is the Unix epoch timestamp (seconds) when the key was created\n Valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
                              "required": true,
                              "constraints": [
                                "must be \u003e= 1735689600",
                                "must be \u003c= 8045740800"
                              ],
                              "constraint_infos": [
                                {
                                  "rule": "assert_required",
                                  "target": "field",
                                  "value_kind": "bool",
                                  "bool_value": true,
                                  "source": "annotation"
                                },
                                {
                                  "rule": "assert_ge",
                                  "target": "field",
                                  "value_kind": "int",
                                  "int_value": 1735689600,
                                  "source": "annotation"
                                },
                                {
                                  "rule": "assert_le",
                                  "target": "field",
                                  "value_kind": "int",
                                  "int_value": 8045740800,
                                  "source": "annotation"
                                }
                              ]
                            }
                          ]
                        }
                      },
                      {
                        "name": "id",
                        "type": "string",
                        "description": "Id is an optional stable key for chain collections.",
                        "constraints": [
                          "maximum size: 256 bytes"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 256,
                            "unit": "bytes",
                            "source": "annotation"
                          }
                        ]
                      }
                    ]
                  }
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "pki",
            "type": "message",
            "description": "PKI material. Loaded from crypto.yaml and merged at runtime.",
            "message": {
              "name": "PKI",
              "package": "operator",
              "description": "PKI holds all PKI material for the cluster.\n\n root_ca is generated once per organization via 'operator init ca'.\n All other fields are generated per-cluster via 'operator init cluster'.\n PKI material lives in crypto.yaml and is merged into OperatorConfig at\n load time. The crypto.yaml file must be kept secret.",
              "fields": [
                {
                  "name": "root_ca",
                  "type": "message (recursive reference: x509.X509CertChain)",
                  "description": "Shared root CA across all clusters (cert + private key)."
                },
                {
                  "name": "cluster_ca",
                  "type": "message (recursive reference: x509.X509CertChain)",
                  "description": "Cluster intermediate CA, signed by root_ca."
                },
                {
                  "name": "node_tls",
                  "type": "message (recursive reference: x509.X509CertChain)",
                  "description": "Per-node TLS server certificates (one per kernel/sentinel replica).",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 1024 elements"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1024,
                      "unit": "elements",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "node_signing_ca",
                  "type": "message (recursive reference: x509.X509CertChain)",
                  "description": "Per-node signing CAs for token issuance (one per kernel replica).",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 1024 elements"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1024,
                      "unit": "elements",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "edge_tls",
                  "type": "message (recursive reference: x509.X509CertChain)",
                  "description": "Edge TLS certificates for gateway and oauth.\n Not used when tls.letsencrypt = true.",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 1024 elements"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1024,
                      "unit": "elements",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "edge_signing_ca",
                  "type": "message (recursive reference: x509.X509CertChain)",
                  "description": "Edge signing CAs.",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 1024 elements"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1024,
                      "unit": "elements",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "kmaker_signing_ca",
                  "type": "message (recursive reference: x509.X509CertChain)",
                  "description": "Kmaker signing CA, signed by cluster_ca and constrained to issue only\n kernel bootstrap leaf certificates."
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "optional_services",
            "type": "message",
            "description": "Optional add-on services.",
            "message": {
              "name": "OptionalServices",
              "package": "operator",
              "description": "OptionalServices controls which optional services are enabled.",
              "fields": [
                {
                  "name": "anthropic",
                  "type": "bool",
                  "description": "Proxy services — when enabled, one replica per gateway node."
                },
                {
                  "name": "openai",
                  "type": "bool"
                },
                {
                  "name": "gitlab",
                  "type": "bool"
                },
                {
                  "name": "github",
                  "type": "bool"
                },
                {
                  "name": "mcp",
                  "type": "bool",
                  "description": "MCP server — one replica when enabled."
                },
                {
                  "name": "saml",
                  "type": "bool",
                  "description": "SAML identity provider bridge — saml_nodes replicas when enabled.\n Disabled by default."
                },
                {
                  "name": "oauth",
                  "type": "bool",
                  "description": "OAuth2/OIDC broker — oauth_nodes replicas when enabled.\n Enabled by default.",
                  "default": true
                },
                {
                  "name": "keycloak",
                  "type": "bool",
                  "description": "Keycloak IDP — production identity provider.\n Replaces mockidp. Enabled by default.",
                  "default": true
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "output_dir",
            "type": "string",
            "description": "Filesystem path where generated Helm charts are written.\n Only used in GENERATE_ONLY mode. Default: \"charts\".",
            "default": "charts",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "web_root",
            "type": "string",
