                      {
                        "name": "jwks_uri",
                        "type": "string",
                        "description": "jwks_uri overrides the auto-discovered JWKS endpoint.",
                        "constraints": [
                          "must be a valid URL (scheme: URL_SCHEME_HTTPS)",
