                      {
                        "name": "ca_pem",
                        "type": "string",
                        "description": "ca_pem is an optional PEM-encoded CA certificate for self-signed IDPs.",
                        "constraints": [
                          "maximum size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "enable",
                        "type": "bool",
                        "description": "enable enables or disables this cluster IDP."
                      },
                      {
                        "name": "trace_id",
                        "type": "string",
                        "constraints": [
                          "maximum size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "noop",
                        "type": "bool"
                      }
                    ]
                  }
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "kmaker",
            "type": "message",
            "description": "kmaker owns cluster bootstrap certificate signing for kernel. Operator\n renders this into kmaker's mounted runtime config and owns the Secret that\n carries kmaker.Config.signing_ca.",
            "message": {
              "name": "Config",
              "package": "kmaker",
              "description": "Config is rendered by operator and mounted into kmaker at startup.",
              "fields": [
                {
                  "name": "cluster_name",
                  "type": "string",
                  "description": "cluster_name is the logical Cavalier cluster this kmaker signs for.",
                  "required": true,
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "listener",
                  "type": "message",
                  "description": "listener is the gRPC bind address for kmaker.",
                  "required": true,
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "message": {
                    "name": "Host",
                    "package": "host",
                    "description": "Host identifies a network endpoint by hostname/IP and port.\n The host field accepts either an FQDN or an IP address (v4/v6).",
                    "fields": [
                      {
                        "name": "host",
                        "type": "string",
                        "description": "Hostname or IP address (e.g. \"api.example.com\" or \"10.0.0.1\").",
                        "required": true,
                        "constraints": [
                          "must be a valid hostname or IP address",
                          "maximum size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_required",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_host",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          },
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "port",
                        "type": "int32",
                        "description": "Port number (1-65535).",
                        "constraints": [
                          "must be a valid network port (1-65535)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_net_port",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "protocol",
                        "type": "enum",
                        "description": "Transport protocol. Default TCP (zero value).",
                        "enum_values": [
                          {
                            "name": "TCP",
                            "number": 0
                          },
                          {
                            "name": "UDP",
                            "number": 1
                          }
                        ]
                      }
                    ]
                  }
                },
                {
                  "name": "logger",
                  "type": "message",
                  "description": "logger configures kmaker process logging.",
                  "message": {
                    "name": "LoggerConfig",
                    "package": "logger",
                    "description": "LoggerConfig represents the configuration for a logger instance.\n It controls the output format, verbosity level, and formatting options.\n\n Example usage:\n   - Development mode with console output and pretty printing for local debugging\n   - Production mode with JSON output and no pretty printing for log aggregation",
                    "fields": [
                      {
                        "name": "name",
                        "type": "string",
                        "description": "Name is the logger name/component identifier",
                        "constraints": [
                          "maximum size: 128 bytes"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 128,
                            "unit": "bytes",
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "format",
                        "type": "enum",
                        "description": "Format determines the output format for log messages (JSON or console)\n Default: FORMAT_JSON in production, FORMAT_CONSOLE in development",
                        "constraint_infos": [
                          {
                            "rule": "assert_enum_defined",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          }
                        ],
                        "enum_values": [
                          {
                            "name": "FORMAT_JSON",
                            "number": 1,
                            "description": "FORMAT_JSON outputs logs as JSON objects, ideal for structured logging and log aggregation systems"
                          },
                          {
                            "name": "FORMAT_CONSOLE",
                            "number": 2,
                            "description": "FORMAT_CONSOLE outputs logs in a human-readable console format, ideal for development and debugging"
                          }
                        ]
                      },
                      {
                        "name": "level",
                        "type": "enum",
                        "description": "Level sets the minimum severity level for log messages to be output\n Messages below this level will be filtered out\n Default: LEVEL_INFO in production, LEVEL_DEBUG in development",
                        "constraint_infos": [
                          {
                            "rule": "assert_enum_defined",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          }
                        ],
                        "enum_values": [
                          {
                            "name": "LEVEL_TRACE",
                            "number": 1,
                            "description": "LEVEL_TRACE is the most verbose log level, used for detailed debugging information"
                          },
                          {
                            "name": "LEVEL_DEBUG",
                            "number": 2,
                            "description": "LEVEL_DEBUG is used for debugging information, less verbose than trace"
                          },
                          {
                            "name": "LEVEL_INFO",
                            "number": 3,
                            "description": "LEVEL_INFO is used for informational messages about normal operations"
                          },
                          {
                            "name": "LEVEL_WARN",
                            "number": 4,
                            "description": "LEVEL_WARN is used for warning messages about potentially problematic situations"
                          },
                          {
                            "name": "LEVEL_ERROR",
                            "number": 5,
                            "description": "LEVEL_ERROR is used for error messages about failures and problems"
                          }
                        ]
                      },
                      {
                        "name": "development",
                        "type": "bool",
                        "description": "Development enables development mode which:\n   - Uses console format by default\n   - Enables stack traces for warnings and errors\n   - Uses more human-readable timestamps\n Default: false (production mode)"
                      },
                      {
                        "name": "pretty_print",
                        "type": "bool",
                        "description": "PrettyPrint enables pretty-printed output for JSON format\n This makes JSON logs more readable but increases output size\n Should be disabled in production for performance\n Default: false"
                      },
                      {
                        "name": "output_paths",
                        "type": "string",
                        "description": "OutputPaths is a list of file paths or URLs to write logs to\n Use \"stdout\" or \"stderr\" for console output\n Example: [\"stdout\", \"/var/log/app.log\"]",
                        "repeated": true,
                        "constraints": [
                          "must be a valid file path (type: PATH_ANY)",
                          "maximum size: 8 elements",
                          "maximum element size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 8,
                            "unit": "elements",
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_file_path",
                            "target": "field",
                            "value_kind": "enum",
                            "enum_value": "PATH_ANY",
                            "source": "annotation"
                          },
                          {
                            "rule": "default_max_element_size",
                            "target": "element",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "error_output_paths",
                        "type": "string",
                        "description": "ErrorOutputPaths is a list of file paths or URLs to write error logs to\n Use \"stderr\" for console error output\n Example: [\"stderr\", \"/var/log/app-errors.log\"]",
                        "repeated": true,
                        "constraints": [
                          "must be a valid file path (type: PATH_ANY)",
                          "maximum size: 8 elements",
                          "maximum element size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 8,
                            "unit": "elements",
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_file_path",
                            "target": "field",
                            "value_kind": "enum",
                            "enum_value": "PATH_ANY",
                            "source": "annotation"
                          },
                          {
                            "rule": "default_max_element_size",
                            "target": "element",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "disable_caller",
                        "type": "bool",
                        "description": "DisableCaller disables automatic inclusion of caller information (file:line) in log entries\n Default: false (caller information is included)"
                      },
                      {
                        "name": "disable_stacktrace",
                        "type": "bool",
                        "description": "DisableStacktrace disables automatic stacktraces for error-level and above log entries\n Default: false (stacktraces are included for errors)"
                      },
                      {
                        "name": "initial_fields",
                        "type": "map",
                        "description": "InitialFields is a map of fields to include in every log entry\n Useful for adding context like service name, version, environment, etc.\n Example: {\"service\": \"api\", \"version\": \"1.0.0\", \"environment\": \"production\"}",
                        "repeated": true,
                        "constraints": [
                          "maximum size: 32 entries",
                          "maximum key size: 32768 bytes (default)",
                          "maximum value size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 32,
                            "unit": "entries",
                            "source": "annotation"
                          },
                          {
                            "rule": "default_max_key_size",
                            "target": "key",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          },
                          {
                            "rule": "default_max_value_size",
                            "target": "value",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ],
                        "map_key_type": "string",
                        "map_value_type": "string"
                      }
                    ]
                  }
                },
                {
                  "name": "cluster_ca",
                  "type": "message (recursive reference: x509.X509Cert)",
                  "description": "cluster_ca holds trust anchors that kernel nodes should trust.",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 16 elements"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 16,
                      "unit": "elements",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "signing_ca",
                  "type": "message (recursive reference: x509.X509CertChain)",
                  "description": "signing_ca is the cluster signing CA used to issue kernel certificates.\n The private key is present in the mounted kmaker config and must be backed\n by a Kubernetes Secret owned by operator.",
                  "required": true,
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "spiffe_prefix",
                  "type": "string",
                  "description": "spiffe_prefix is the deployment prefix for kernel SPIFFE URI SANs.\n Certificates minted here receive spiffe://\u003cspiffe_prefix\u003e/kernel.",
                  "default": "local/dev",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "token_audience",
                  "type": "string",
                  "description": "token_audience is the required Kubernetes TokenReview audience.",
                  "default": "kmaker",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "kernel_service_accounts",
                  "type": "message",
                  "description": "kernel_service_accounts are Kubernetes service accounts allowed to request\n kernel certificates. Empty means namespace=cavalier, name=kernel.",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 32 elements"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32,
                      "unit": "elements",
                      "source": "annotation"
                    }
                  ],
                  "message": {
                    "name": "KernelServiceAccount",
                    "package": "kmaker",
                    "fields": [
                      {
                        "name": "namespace",
                        "type": "string",
                        "required": true,
                        "constraints": [
                          "maximum size: 128 bytes"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_required",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 128,
                            "unit": "bytes",
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "name",
                        "type": "string",
                        "required": true,
                        "constraints": [
                          "maximum size: 128 bytes"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_required",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 128,
                            "unit": "bytes",
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "trace_id",
                        "type": "string",
                        "constraints": [
                          "maximum size: 32768 bytes (default)"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "default_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 32768,
                            "defaulted": true,
                            "unit": "bytes",
                            "source": "default_bound"
                          }
                        ]
                      },
                      {
                        "name": "noop",
                        "type": "bool"
                      }
                    ]
                  }
                },
                {
                  "name": "kernel_cert_lifetime_seconds",
                  "type": "int64",
                  "description": "kernel_cert_lifetime_seconds caps issued kernel certificate lifetimes.",
                  "default": 86400,
                  "constraints": [
                    "duration constraint: DURATION_TYPE_POSITIVE"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_duration",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "DURATION_TYPE_POSITIVE",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "tls",
                  "type": "message (recursive reference: x509.X509CertChain)",
                  "description": "tls is the optional serving certificate for kmaker's own gRPC listener.\n When unset, kmaker starts without transport TLS for local/dev only."
                },
                {
                  "name": "health_probe_port",
                  "type": "int32",
                  "description": "health_probe_port is the plaintext gRPC port for k8s health probes.\n Kmaker's hand-written bootstrap bypasses the generated ServiceManager,\n so this field must be on Kmaker.Config (not only on Grpcconfig.Config).\n Default matches the platform-wide health probe port.",
                  "default": 8444
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

fields.description:
InitialFields is a map of fields to include in every log entry
 Useful for adding context like service name, version, environment, etc.
 Example: {"service": "api", "version": "1.0.0", "environment": "production"}

types.schema_json:
{
  "name": "OptionalServices",
  "package": "operator",
  "description": "OptionalServices controls which optional services are enabled.",
  "fields": [
    {
      "name": "anthropic",
      "type": "bool",
      "description": "Proxy services — when enabled, one replica per gateway node."
    },
    {
      "name": "openai",
      "type": "bool"
    },
    {
      "name": "gitlab",
      "type": "bool"
    },
    {
      "name": "github",
      "type": "bool"
    },
    {
      "name": "mcp",
      "type": "bool",
      "description": "MCP server — one replica when enabled."
    },
    {
      "name": "saml",
      "type": "bool",
      "description": "SAML identity provider bridge — saml_nodes replicas when enabled.\n Disabled by default."
    },
    {
      "name": "oauth",
      "type": "bool",
      "description": "OAuth2/OIDC broker — oauth_nodes replicas when enabled.\n Enabled by default.",
      "default": true
    },
    {
      "name": "keycloak",
      "type": "bool",
      "description": "Keycloak IDP — production identity provider.\n Replaces mockidp. Enabled by default.",
      "default": true
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}

{
  "name": "PKI",
  "package": "operator",
  "description": "PKI holds all PKI material for the cluster.\n\n root_ca is generated once per organization via 'operator init ca'.\n All other fields are generated per-cluster via 'operator init cluster'.\n PKI material lives in crypto.yaml and is merged into OperatorConfig at\n load time. The crypto.yaml file must be kept secret.",
  "fields": [
    {
