{
  "name": "ServiceConfigState",
  "package": "grpcconfig",
  "description": "ServiceConfigState delivers runtime configuration (OPA policy, TLS, logging)\n to all RPC services. The cluster writes the config; services subscribe\n via OnChange to receive updates.",
  "fields": [
    {
      "name": "config",
      "type": "message",
      "message": {
        "name": "Config",
        "package": "grpcconfig",
        "description": "Config is the single configuration type for all services.\n\n Bootstrap fields (endpoints, instance_id, private_key, trusted_cas) are loaded\n from YAML at boot and used to connect to the cluster.\n\n Runtime fields (ping_interval_ms, rebalance_interval_ms, listen_address,\n max_request_size, request_timeout_seconds, logger, shutdown_timeout_seconds)\n are delivered by the cluster via ServiceConfigState and can change at any time.\n\n TLS certificates are obtained automatically by the servicemanager via X509Mint\n after token exchange — they are not part of the config.",
        "fields": [
          {
            "name": "endpoints",
            "type": "message",
            "description": "Cluster endpoints. Set in bootstrap file; can be updated at runtime\n via ServiceConfigState to add/remove endpoints dynamically.",
            "repeated": true,
            "constraints": [
              "maximum size: 32 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "Host",
              "package": "host",
              "description": "Host identifies a network endpoint by hostname/IP and port.\n The host field accepts either an FQDN or an IP address (v4/v6).",
              "fields": [
                {
                  "name": "host",
                  "type": "string",
                  "description": "Hostname or IP address (e.g. \"api.example.com\" or \"10.0.0.1\").",
                  "required": true,
                  "constraints": [
                    "must be a valid hostname or IP address",
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_host",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "port",
                  "type": "int32",
                  "description": "Port number (1-65535).",
                  "constraints": [
                    "must be a valid network port (1-65535)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_net_port",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "protocol",
                  "type": "enum",
                  "description": "Transport protocol. Default TCP (zero value).",
                  "enum_values": [
                    {
                      "name": "TCP",
                      "number": 0
                    },
                    {
                      "name": "UDP",
                      "number": 1
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "instance_id",
            "type": "string",
            "description": "instance_id uniquely identifies this running instance/replica.\n Used for leader elections on boundaries with (spec.leader) = true.\n If empty, a random ID is generated at client creation time.",
            "constraints": [
              "maximum size: 128 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "private_key",
            "type": "message",
            "description": "private_key is used to mint throwaway bootstrap JWTs for the\n token exchange flow. The kid is in private_key.id;\n identity (subject/audience) comes from the delegate looked up\n by TokenExchanger using the matching kid.\n If absent, cloud-native authentication is attempted.",
            "message": {
              "name": "Key",
              "package": "key",
              "description": "Key represents a private cryptographic key (alias for ProtoKey).",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is a unique identifier for the key (corresponds to kid in JWK)",
                  "required": true,
                  "constraints": [
                    "maximum size: 256 bytes",
                    "minimum size: 1"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 256,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_min_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "base64",
                  "type": "string",
                  "description": "Base64 contains the base64url-encoded PEM private key block",
                  "required": true,
                  "constraints": [
                    "must be base64 encoded",
                    "encoding type: ENC_TYPE_KEY_PRIVATE_ANY",
                    "maximum size: 16384 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 16384,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_base64",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_enc_type",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "ENC_TYPE_KEY_PRIVATE_ANY",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "created",
                  "type": "int64",
                  "description": "Created is the Unix epoch timestamp (seconds) when the key was created\n Valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
                  "required": true,
                  "constraints": [
                    "must be \u003e= 1735689600",
                    "must be \u003c= 8045740800"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_ge",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1735689600,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_le",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8045740800,
                      "source": "annotation"
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "ping_interval_ms",
            "type": "int32",
            "description": "ping_interval_ms controls how often each endpoint is pinged for latency measurement.\n Default: 5000 (5 seconds)",
            "default": 5000
          },
          {
            "name": "rebalance_interval_ms",
            "type": "int32",
            "description": "rebalance_interval_ms controls how often the active connection is re-evaluated\n based on latency. Default: 10000 (10 seconds)",
            "default": 10000
          },
          {
            "name": "listen_address",
            "type": "message (recursive reference: host.Host)",
            "description": "listen_address is the bind address for the gRPC server. Default port 8443.",
            "required": true,
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "max_request_size",
            "type": "int64",
            "description": "max_request_size is the maximum request size in bytes.\n Must be greater than 0. Default: 10MB (10485760 bytes)",
            "default": 10485760,
            "constraints": [
              "must be \u003e 0"
            ],
            "constraint_infos": [
              {
                "rule": "assert_gt",
                "target": "field",
                "value_kind": "int",
                "int_value": 0,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "request_timeout_seconds",
            "type": "int64",
            "description": "request_timeout_seconds is the timeout for client requests.\n Must be positive. Default: 30 seconds.",
            "default": 30,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ],
            "constraint_infos": [
              {
                "rule": "assert_duration",
                "target": "field",
                "value_kind": "enum",
                "enum_value": "DURATION_TYPE_POSITIVE",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "logger",
            "type": "message",
            "description": "logger configures the logger for the service.\n Controls log format (JSON/console), level, output paths, and more.",
            "message": {
              "name": "LoggerConfig",
              "package": "logger",
              "description": "LoggerConfig represents the configuration for a logger instance.\n It controls the output format, verbosity level, and formatting options.\n\n Example usage:\n   - Development mode with console output and pretty printing for local debugging\n   - Production mode with JSON output and no pretty printing for log aggregation",
              "fields": [
                {
                  "name": "name",
                  "type": "string",
                  "description": "Name is the logger name/component identifier",
                  "constraints": [
                    "maximum size: 128 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 128,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "format",
                  "type": "enum",
                  "description": "Format determines the output format for log messages (JSON or console)\n Default: FORMAT_JSON in production, FORMAT_CONSOLE in development",
                  "constraint_infos": [
                    {
                      "rule": "assert_enum_defined",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "enum_values": [
                    {
                      "name": "FORMAT_JSON",
                      "number": 1,
                      "description": "FORMAT_JSON outputs logs as JSON objects, ideal for structured logging and log aggregation systems"
                    },
                    {
                      "name": "FORMAT_CONSOLE",
                      "number": 2,
                      "description": "FORMAT_CONSOLE outputs logs in a human-readable console format, ideal for development and debugging"
                    }
                  ]
                },
                {
                  "name": "level",
                  "type": "enum",
                  "description": "Level sets the minimum severity level for log messages to be output\n Messages below this level will be filtered out\n Default: LEVEL_INFO in production, LEVEL_DEBUG in development",
                  "constraint_infos": [
                    {
                      "rule": "assert_enum_defined",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "enum_values": [
                    {
                      "name": "LEVEL_TRACE",
                      "number": 1,
                      "description": "LEVEL_TRACE is the most verbose log level, used for detailed debugging information"
                    },
                    {
                      "name": "LEVEL_DEBUG",
                      "number": 2,
                      "description": "LEVEL_DEBUG is used for debugging information, less verbose than trace"
                    },
                    {
                      "name": "LEVEL_INFO",
                      "number": 3,
                      "description": "LEVEL_INFO is used for informational messages about normal operations"
                    },
                    {
                      "name": "LEVEL_WARN",
                      "number": 4,
                      "description": "LEVEL_WARN is used for warning messages about potentially problematic situations"
                    },
                    {
                      "name": "LEVEL_ERROR",
                      "number": 5,
                      "description": "LEVEL_ERROR is used for error messages about failures and problems"
                    }
                  ]
                },
                {
                  "name": "development",
                  "type": "bool",
                  "description": "Development enables development mode which:\n   - Uses console format by default\n   - Enables stack traces for warnings and errors\n   - Uses more human-readable timestamps\n Default: false (production mode)"
                },
                {
                  "name": "pretty_print",
                  "type": "bool",
                  "description": "PrettyPrint enables pretty-printed output for JSON format\n This makes JSON logs more readable but increases output size\n Should be disabled in production for performance\n Default: false"
                },
                {
                  "name": "output_paths",
                  "type": "string",
                  "description": "OutputPaths is a list of file paths or URLs to write logs to\n Use \"stdout\" or \"stderr\" for console output\n Example: [\"stdout\", \"/var/log/app.log\"]",
                  "repeated": true,
                  "constraints": [
                    "must be a valid file path (type: PATH_ANY)",
                    "maximum size: 8 elements",
                    "maximum element size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8,
                      "unit": "elements",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_file_path",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "PATH_ANY",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_element_size",
                      "target": "element",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "error_output_paths",
                  "type": "string",
                  "description": "ErrorOutputPaths is a list of file paths or URLs to write error logs to\n Use \"stderr\" for console error output\n Example: [\"stderr\", \"/var/log/app-errors.log\"]",
                  "repeated": true,
                  "constraints": [
                    "must be a valid file path (type: PATH_ANY)",
                    "maximum size: 8 elements",
                    "maximum element size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8,
                      "unit": "elements",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_file_path",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "PATH_ANY",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_element_size",
                      "target": "element",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "disable_caller",
                  "type": "bool",
                  "description": "DisableCaller disables automatic inclusion of caller information (file:line) in log entries\n Default: false (caller information is included)"
                },
                {
                  "name": "disable_stacktrace",
                  "type": "bool",
                  "description": "DisableStacktrace disables automatic stacktraces for error-level and above log entries\n Default: false (stacktraces are included for errors)"
                },
                {
                  "name": "initial_fields",
                  "type": "map",
                  "description": "InitialFields is a map of fields to include in every log entry\n Useful for adding context like service name, version, environment, etc.\n Example: {\"service\": \"api\", \"version\": \"1.0.0\", \"environment\": \"production\"}",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 32 entries",
                    "maximum key size: 32768 bytes (default)",
                    "maximum value size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32,
                      "unit": "entries",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_key_size",
                      "target": "key",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    },
                    {
                      "rule": "default_max_value_size",
                      "target": "value",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ],
                  "map_key_type": "string",
                  "map_value_type": "string"
                }
              ]
            }
          },
          {
            "name": "shutdown_timeout_seconds",
            "type": "int64",
            "description": "shutdown_timeout_seconds is the maximum time (in seconds) to wait for graceful\n shutdown after SIGTERM before forcing immediate shutdown.\n Must be positive. Default: 30 seconds.",
            "default": 30,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ],
            "constraint_infos": [
              {
                "rule": "assert_duration",
                "target": "field",
                "value_kind": "enum",
                "enum_value": "DURATION_TYPE_POSITIVE",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "max_concurrent_streams",
            "type": "int32",
            "description": "max_concurrent_streams limits the number of concurrent gRPC streams per connection.\n Prevents resource exhaustion from clients opening unlimited streams.\n Default: 100. Set to 0 to use the gRPC library default (unlimited).",
            "default": 100
          },
          {
            "name": "max_send_msg_size",
            "type": "int64",
            "description": "max_send_msg_size is the maximum response message size in bytes.\n Prevents the server from sending responses that could OOM clients.\n Default: 16MB (16777216 bytes). Set to 0 to use the gRPC library default.",
            "default": 16777216
          },
          {
            "name": "keepalive_min_time_seconds",
            "type": "int64",
            "description": "keepalive_min_time_seconds is the minimum interval clients must wait between\n keepalive pings. Clients pinging more frequently are disconnected.\n Default: 30 seconds. Set to 0 to disable enforcement.",
            "default": 30
          },
          {
            "name": "trusted_cas",
            "type": "message",
            "description": "trusted_cas is the explicit list of CA certificates trusted for SPIFFE TLS\n verification when connecting to cluster endpoints. It must not be empty.",
            "repeated": true,
            "constraints": [
              "maximum size: 32 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "X509Cert",
              "package": "x509",
              "description": "ProtoCert represents an X.509 certificate.\n The certificate is stored as a base64-encoded PEM block.\n Use NewProtoCert() in Go with DER-encoded certificate bytes to create.",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is a unique identifier for the certificate",
                  "constraints": [
                    "maximum size: 256 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 256,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "base64",
                  "type": "string",
                  "description": "Base64 contains the base64url-encoded PEM certificate block",
                  "required": true,
                  "constraints": [
                    "must be base64 encoded",
                    "maximum size: 16384 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 16384,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_base64",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "spiffe_trust_domain",
            "type": "string",
            "description": "spiffe_trust_domain is the SPIFFE URI authority: a globally unique instance\n name for this autonomous-system instance (need not be a DNS domain).\n It must not contain '/', a scheme, query, or fragment, and carries no path.\n Service identity is built by the generated sys/spiffe helper as:\n   spiffe://\u003cspiffe_trust_domain\u003e/system/\u003clocation_path...\u003e/services/\u003cservice_label\u003e\n If empty, SPIFFE IDs are not set on health reports or X509 URI SANs.",
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "location_path",
            "type": "string",
            "description": "location_path is this service instance's topology path under /system —\n opaque, tag-delimited, slash-separated segments, arity not fixed\n (e.g. \"aws/123456789012/us-east-1a/cluster-7/team-a\"). Segments follow the\n SPIFFE segment grammar and must not be reserved tags. Supplied by the\n operator/deployment from runtime config (where the service runs); it is\n not a token claim. May be empty (no topology tiers).",
            "constraints": [
              "maximum size: 512 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 512,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "disk_persistence",
            "type": "message",
            "description": "disk_persistence is an init-time/bootstrap setting that enables\n ServiceManager-owned redo-log lifecycle for generated service_store stores.\n When present at ServiceManager creation, the generated ServiceManager opens\n the per-store redo logs, exposes those handles to service code, and owns\n scheduled compaction/roll. It is not hot-reloaded; when absent, typed\n diskstore helpers remain available but no managed roll loop is started.",
            "message": {
              "name": "DiskPersistenceConfig",
              "package": "diskstore",
              "description": "DiskPersistenceConfig configures the SM-managed persistence component that\n automates the redo-log lifecycle (UC2) for service_store-annotated types.\n It is embedded in the ServiceManager config.",
              "fields": [
                {
                  "name": "roll_interval_seconds",
                  "type": "int64",
                  "description": "roll_interval_seconds is the compaction/roll period. Also bounds the\n per-node deterministic roll offset (hash(node-id) % roll_interval).",
                  "default": 86400,
                  "constraints": [
                    "duration constraint: DURATION_TYPE_POSITIVE"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_duration",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "DURATION_TYPE_POSITIVE",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "archive_count",
                  "type": "uint32",
                  "description": "archive_count is how many rolled archive files to retain.",
                  "default": 3
                },
                {
                  "name": "dir",
                  "type": "string",
                  "description": "dir is the base directory (on the service's own volume) for the\n active / building / temp / archive files.",
                  "required": true,
                  "constraints": [
                    "maximum size: 4096 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 4096,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "file_permission",
                  "type": "message",
                  "description": "file_permission is the Unix permission for the data files (e.g. 0600).",
                  "message": {
                    "name": "Permission",
                    "package": "filesystem",
                    "description": "Permission represents Unix-style file permissions (e.g., 755).\n Each field is a 3-bit mask: read (4) + write (2) + execute (1).",
                    "fields": [
                      {
                        "name": "owner",
                        "type": "uint32",
                        "description": "owner permission bits (0-7)",
                        "constraints": [
                          "must be \u003e= 0",
                          "must be \u003c= 7"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_ge",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 0,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_le",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 7,
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "group",
                        "type": "uint32",
                        "description": "group permission bits (0-7)",
                        "constraints": [
                          "must be \u003e= 0",
                          "must be \u003c= 7"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_ge",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 0,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_le",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 7,
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "other",
                        "type": "uint32",
                        "description": "other permission bits (0-7)",
                        "constraints": [
                          "must be \u003e= 0",
                          "must be \u003c= 7"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_ge",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 0,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_le",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 7,
                            "source": "annotation"
                          }
                        ]
                      }
                    ]
                  }
                },
                {
                  "name": "compression",
                  "type": "enum",
                  "description": "compression for rolled/archived files + snapshots; the live append tail\n stays uncompressed.",
                  "constraint_infos": [
                    {
                      "rule": "assert_enum_defined",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "enum_values": [
                    {
                      "name": "COMPRESSION_NONE",
                      "number": 0
                    },
                    {
                      "name": "COMPRESSION_GZ",
                      "number": 1
                    },
                    {
                      "name": "COMPRESSION_BZ",
                      "number": 2
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "anonymize_hmac_key",
            "type": "bytes",
            "description": "anonymize_hmac_key is the per-deployment data-entitlement ANONYMIZE secret:\n the keyed-HMAC key the generated service wrapper supplies to Sanitize\u003cT\u003e so\n a value pseudonymizes to the same surrogate at any depth, across services\n and restarts. Required only by services whose records carry\n ANONYMIZE-capable (spec.redact) fields — the generated pseudonymize\n primitives fail loud on an empty key.",
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "health_probe_port",
            "type": "int32",
            "description": "health_probe_port is the port for a separate PLAINTEXT gRPC listener that\n serves ONLY grpc.health.v1. k8s kubelet probes are plaintext-only and\n cannot speak TLS, so the main TLS port (listen_address) is invisible to\n them. This listener runs on a completely separate grpc.Server / tonic\n Server / NettyServerBuilder with no TLS, no auth interceptors, and no\n business services registered — isolation is the security argument.\n The health status reflects the same StatusSink-driven state as the TLS\n health endpoint: NOT_SERVING until bootstrap completes, then tracks\n handler health (UNHEALTHY → NOT_SERVING, recovery → SERVING).\n Default: 8444. Set to 0 to disable the plaintext health probe listener.",
            "default": 8444
          }
        ]
      }
    }
  ]
}

fields.description:
InitialFields is a map of fields to include in every log entry
 Useful for adding context like service name, version, environment, etc.
 Example: {"service": "api", "version": "1.0.0", "environment": "production"}

types.schema_json:
{
  "name": "ServiceInstanceHealth",
  "package": "healthreport",
  "description": "ServiceInstanceHealth captures the health, load, and reachability of a\n single running instance of a microservice. The composite key\n \"service_id@instance_id\" is set by the server from the caller's token claims.",
  "fields": [
    {
      "name": "id",
      "type": "string",
      "description": "Composite key: \"service:fleetwood@uuid\" — set by server from token claims",
      "constraints": [
        "maximum size: 256 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 256,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "service_id",
      "type": "string",
      "constraints": [
        "maximum size: 128 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 128,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "instance_id",
      "type": "string",
      "constraints": [
        "maximum size: 128 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 128,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "grpc_endpoint",
      "type": "message",
      "description": "Reachability",
      "message": {
        "name": "Host",
        "package": "host",
        "description": "Host identifies a network endpoint by hostname/IP and port.\n The host field accepts either an FQDN or an IP address (v4/v6).",
        "fields": [
          {
            "name": "host",
            "type": "string",
            "description": "Hostname or IP address (e.g. \"api.example.com\" or \"10.0.0.1\").",
            "required": true,
            "constraints": [
              "must be a valid hostname or IP address",
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_host",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "port",
            "type": "int32",
            "description": "Port number (1-65535).",
            "constraints": [
              "must be a valid network port (1-65535)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_net_port",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "protocol",
            "type": "enum",
            "description": "Transport protocol. Default TCP (zero value).",
            "enum_values": [
              {
                "name": "TCP",
                "number": 0
              },
              {
                "name": "UDP",
                "number": 1
              }
            ]
          }
        ]
      }
    },
    {
      "name": "http_endpoint",
      "type": "message (recursive reference: host.Host)"
    },
    {
      "name": "status",
      "type": "enum",
      "description": "Health",
      "constraint_infos": [
        {
          "rule": "assert_enum_defined",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        }
      ],
      "enum_values": [
        {
          "name": "INSTANCE_STATUS_STARTING",
          "number": 0
        },
        {
          "name": "INSTANCE_STATUS_HEALTHY",
          "number": 1
        },
        {
          "name": "INSTANCE_STATUS_DEGRADED",
          "number": 2
        },
        {
          "name": "INSTANCE_STATUS_DRAINING",
          "number": 3
        },
        {
          "name": "INSTANCE_STATUS_UNHEALTHY",
          "number": 4
        }
      ]
    },
    {
      "name": "cpu_usage",
      "type": "double",
      "description": "Load (auto-collected from runtime)",
      "constraints": [
        "must be \u003e= 0.000000",
        "must be \u003c= 100.000000"
      ],
      "constraint_infos": [
        {
          "rule": "assert_float",
          "target": "field",
          "value_kind": "float",
          "float_value": 0,
          "operator": "ge",
          "source": "annotation"
        },
        {
          "rule": "assert_float",
          "target": "field",
          "value_kind": "float",
          "float_value": 100,
          "operator": "le",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "memory_used_bytes",
      "type": "int64",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "memory_max_bytes",
      "type": "int64",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "active_requests",
      "type": "int32",
      "description": "Load (from grpcserver metrics)",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "max_concurrent_requests",
      "type": "int32",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "request_rate",
      "type": "double",
      "constraints": [
        "must be \u003e= 0.000000"
      ],
      "constraint_infos": [
        {
          "rule": "assert_float",
          "target": "field",
          "value_kind": "float",
          "float_value": 0,
          "operator": "ge",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "p50_latency_us",
      "type": "int64",
      "description": "Performance (from grpcserver metrics)",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "p99_latency_us",
      "type": "int64",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "error_rate",
      "type": "double",
      "constraints": [
        "must be \u003e= 0.000000",
        "must be \u003c= 1.000000"
      ],
      "constraint_infos": [
        {
          "rule": "assert_float",
          "target": "field",
          "value_kind": "float",
          "float_value": 0,
          "operator": "ge",
          "source": "annotation"
        },
        {
          "rule": "assert_float",
          "target": "field",
          "value_kind": "float",
          "float_value": 1,
          "operator": "le",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "version",
      "type": "string",
      "description": "Routing metadata",
      "constraints": [
        "maximum size: 64 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "labels",
      "type": "map",
      "repeated": true,
      "constraints": [
        "maximum size: 32 entries",
        "maximum key size: 32768 bytes (default)",
        "maximum value size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32,
          "unit": "entries",
          "source": "annotation"
        },
        {
          "rule": "default_max_key_size",
          "target": "key",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        },
        {
          "rule": "default_max_value_size",
          "target": "value",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ],
      "map_key_type": "string",
      "map_value_type": "string"
    },
    {
      "name": "started_at_ms",
      "type": "int64",
      "description": "Timestamps",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "timestamp_ms",
      "type": "int64",
      "constraints": [
        "must be \u003e= 0"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 0,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "spiffe_id",
      "type": "string",
      "description": "SPIFFE identity\n spiffe_id is the full SPIFFE URI for this instance, built by the owning\n service manager via the generated sys/spiffe helper (service_spiffe_id) —\n never hand-formatted. It is one of the durable materialization points of\n the computed identity (health identity, X509 URI SAN, workload keys).\n Format: spiffe://\u003ctrust_domain\u003e/system/\u003clocation...\u003e/services/\u003cservice\u003e[/workloads/\u003cchild\u003e...]\n Service:  spiffe://example.com/system/aws/us-east-1a/cluster-7/services/identity\n Workload: spiffe://example.com/system/aws/us-east-1a/cluster-7/services/mud-controller/workloads/agent-42\n Consumers needing the location-agnostic service identity parse it with\n service_path_from_spiffe (the bare label, plus any /workloads suffix).",
      "constraints": [
        "maximum size: 512 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 512,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    }
  ]
}

{
