            "type": "string",
            "description": "N is the RSA modulus (base64url encoded without padding)",
            "constraints": [
              "must be base64 encoded",
              "maximum size: 1024 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_base64",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "crv",
            "type": "string",
            "description": "Crv is the elliptic curve name (e.g., P-256, P-384, P-521, Ed25519)",
            "constraints": [
              "maximum size: 64 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "x",
            "type": "string",
            "description": "X is the x coordinate for EC keys or the public key for OKP (base64url encoded without padding)",
            "constraints": [
              "must be base64 encoded",
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_base64",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "y",
            "type": "string",
            "description": "Y is the y coordinate for EC keys (base64url encoded without padding, not used for OKP)",
            "constraints": [
              "must be base64 encoded",
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_base64",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
          },
          {
            "name": "exp",
            "type": "int64",
            "description": "Exp is the expiration in epoch seconds. This is not part of the JWK spec as the spec does\n not specify how to handle public key expiration.\n When stored in a collection with epoch_expiration, the state store computes TTL = exp - now\n and auto-evicts the entry on expiry."
          },
          {
            "name": "created",
            "type": "int64",
            "description": "Created is the Unix epoch timestamp (seconds) when the key was created (optional).\n If set, valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
            "constraints": [
              "must be \u003e= 1735689600",
              "must be \u003c= 8045740800"
            ],
            "constraint_infos": [
              {
                "rule": "assert_ge",
                "target": "field",
                "value_kind": "int",
                "int_value": 1735689600,
                "source": "annotation"
              },
              {
                "rule": "assert_le",
                "target": "field",
                "value_kind": "int",
                "int_value": 8045740800,
                "source": "annotation"
              }
            ]
          }
        ]
      }
    },
    {
      "name": "found",
      "type": "bool"
    }
  ]
}

