types.description:
GraphFieldOption configures how a single proto field maps to graph storage.
 Applied via (spec.graph) on individual fields. Only fields with this
 annotation are persisted; all others are omitted by default.

 Example usage:
   string id = 1 [(spec.graph) = {mode: PREDICATE, index: "exact", upsert: true}];
   string email = 2 [(spec.graph) = {mode: PREDICATE, index: "exact"}];
   NetworkInfo network = 3 [(spec.graph) = {mode: PREDICATE, reverse: true}];
   map<string, string> labels = 4 [(spec.graph) = {mode: INCLUDE}];
   int32 internal_counter = 5; // no annotation — omitted from graph storage

types.schema_json:
{
  "name": "GraphFieldOption",
  "package": "spec",
  "description": "GraphFieldOption configures how a single proto field maps to graph storage.\n Applied via (spec.graph) on individual fields. Only fields with this\n annotation are persisted; all others are omitted by default.\n\n Example usage:\n   string id = 1 [(spec.graph) = {mode: PREDICATE, index: \"exact\", upsert: true}];\n   string email = 2 [(spec.graph) = {mode: PREDICATE, index: \"exact\"}];\n   NetworkInfo network = 3 [(spec.graph) = {mode: PREDICATE, reverse: true}];\n   map\u003cstring, string\u003e labels = 4 [(spec.graph) = {mode: INCLUDE}];\n   int32 internal_counter = 5; // no annotation — omitted from graph storage",
  "fields": [
    {
      "name": "mode",
      "type": "enum",
      "description": "mode controls whether this field is a graph predicate, included as JSON,\n or omitted entirely (UNSPECIFIED / absent).",
      "enum_values": [
        {
          "name": "GRAPH_MODE_INCLUDE",
          "number": 1,
          "description": "Field is stored as a JSON blob. Not queryable, but preserved\n for round-trip fidelity. Suitable for maps, collections, and nested data\n that doesn't need graph traversal or filtering."
        },
        {
          "name": "GRAPH_MODE_PREDICATE",
          "number": 2,
          "description": "Field becomes a graph predicate with an index. Scalar fields map to\n typed predicates (string, int, float, bool, datetime). Message fields\n become uid edges — the target message must also have (spec.graph)\n annotations and exactly one upsert field.\n NOT valid on repeated fields or maps — use INCLUDE for collections."
        }
      ]
    },
    {
      "name": "index",
      "type": "string",
      "description": "index is required when mode is PREDICATE and the field is a scalar type.\n Ignored for uid edges (message fields) and INCLUDE mode.\n Values depend on the graph store type:\n   string:   \"exact\", \"hash\", \"term\", \"fulltext\", \"trigram\"\n   int/uint: \"int\"\n   float:    \"float\"\n   bool:     \"bool\"\n   datetime: \"hour\", \"day\", \"month\", \"year\"",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "upsert",
      "type": "bool",
      "description": "upsert marks this field as the identity predicate for upsert mutations.\n Exactly one field per message must be marked upsert: true when the message\n is the target of a uid edge from another message.\n Only valid with mode: PREDICATE."
    },
    {
      "name": "reverse",
      "type": "bool",
      "description": "reverse marks a uid edge predicate as reverse-traversable, enabling\n traversal from child to parent (e.g., given a NetworkInfo node, find all\n ServiceInstances that reference it).\n Only valid with mode: PREDICATE on message-type fields."
    }
  ]
}

