{
  "name": "MethodCollection",
  "package": "spec",
  "description": "MethodCollection marks an RPC as a collection-returning read and declares its\n shape. The author declares intent plus a bound; tacplus derives transport,\n tiering, flow control, and lifecycle. See docs/API.md for the full model.",
  "fields": [
    {
      "name": "mode",
      "type": "enum",
      "description": "mode is required: SNAPSHOT (finite) or WATCH (open-ended).",
      "enum_values": [
        {
          "name": "COLLECTION_MODE_SNAPSHOT",
          "number": 1,
          "description": "SNAPSHOT: a finite point-in-time set that terminates. Requires max_items.\n tacplus derives the delivery tier (inline / accumulated-stream / cursor)\n from max_items and the response's max element size."
        },
        {
          "name": "COLLECTION_MODE_WATCH",
          "number": 2,
          "description": "WATCH: an open-ended, change-driven stream (snapshot-then-deltas). Forbids\n max_items; uses a bounded replay ring (replay_depth) for resume."
        },
        {
          "name": "COLLECTION_MODE_PAGE",
          "number": 3,
          "description": "PAGE: a client-driven, resumable, windowed GET (unary). The caller pages\n through a finite set with an opaque keyset page_token over order_by; each\n page is bounded by page_size (capped at the trust-tier ceiling). Forbids\n max_items/replay_depth. See archive/RPC_PATTERNS_AND_VERBS_PLAN.md §4."
        }
      ]
    },
    {
      "name": "order_by",
      "type": "string",
      "description": "order_by names the response fields that define a stable total order.\n Required for both modes (pagination cursors and the snapshot/delta boundary\n are only coherent over a stable order). tacplus appends a unique tiebreaker\n if these are not already total.",
      "repeated": true,
      "constraints": [
        "maximum size: 1024 elements (default)",
        "maximum element size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1024,
          "defaulted": true,
          "unit": "elements",
          "source": "default_bound"
        },
        {
          "rule": "default_max_element_size",
          "target": "element",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "max_items",
      "type": "uint32",
      "description": "max_items is the required, positive, finite item cap for SNAPSHOT reads.\n It is the routing key: tacplus computes max_items * max_item_bytes to pick\n the delivery tier. Forbidden on WATCH. Zero/unset on SNAPSHOT is an error."
    },
    {
      "name": "replay_depth",
      "type": "uint32",
      "description": "replay_depth is the WATCH replay-ring depth (count of retained changes).\n Optional; defaults to a platform constant. Forbidden on SNAPSHOT."
    },
    {
      "name": "default_page_size",
      "type": "uint32",
      "description": "default_page_size is the PAGE per-page window used when the request omits\n page_size. Required positive on PAGE; must be \u003c= the trust-tier ceiling.\n Forbidden on SNAPSHOT/WATCH. PAGE only."
    }
  ]
}

