{
  "name": "EntitlementEvalResult",
  "package": "userentitlements",
  "description": "EntitlementEvalResult is the output of the entitlements OPA policy.\n The policy returns a TokenEntitlements directly — kernel embeds it in the\n JWT service_entitlements claim without any further expansion.",
  "fields": [
    {
      "name": "token_entitlements",
      "type": "message",
      "description": "token_entitlements holds the per-service RPC grants returned by OPA.",
      "message": {
        "name": "TokenEntitlements",
        "package": "entitlements",
        "description": "TokenEntitlements holds compressed C2S entitlements embedded in user tokens.\n OPA returns this structure directly; the token authority embeds it in the JWT service_entitlements claim.\n grants may contain exact or wildcard grant tokens; generated helpers normalize them before authorization.",
        "fields": [
          {
            "name": "grants",
            "type": "string",
            "description": "grants is a flat list of generated grant tokens, e.g. PACKAGE_SERVICE_RPC.",
            "repeated": true,
            "constraints": [
              "maximum size: 1024 elements (default)",
              "maximum element size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "defaulted": true,
                "unit": "elements",
                "source": "default_bound"
              },
              {
                "rule": "default_max_element_size",
                "target": "element",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "data_grants",
            "type": "string",
            "description": "data_grants is a flat list of generated data-entitlement grant tokens, e.g.\n PACKAGE_RECORD_FIELD. A data grant names what the caller may SEE RAW: a MAY_*\n redact field with a matching grant egresses raw; absent a grant the field gets\n its most-protective default (MAY_REDACT -\u003e REDACT, MAY_ANONYMIZE -\u003e ANONYMIZE).\n Stamped by OPA at token-exchange time alongside grants — an identity property,\n never a request parameter.",
            "repeated": true,
            "constraints": [
              "maximum size: 1024 elements (default)",
              "maximum element size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "defaulted": true,
                "unit": "elements",
                "source": "default_bound"
              },
              {
                "rule": "default_max_element_size",
                "target": "element",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "azp",
            "type": "string",
            "description": "azp restricts these entitlements to tokens with a matching authorized party.\n Empty = entitlements apply regardless of azp.",
            "repeated": true,
            "constraints": [
              "maximum size: 1024 elements (default)",
              "maximum element size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1024,
                "defaulted": true,
                "unit": "elements",
                "source": "default_bound"
              },
              {
                "rule": "default_max_element_size",
                "target": "element",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          }
        ]
      }
    },
    {
      "name": "all_entitlements",
      "type": "bool",
      "description": "all_entitlements grants unrestricted access to all services and RPCs.\n When true, kernel sets service_entitlements={\"all\":true} in the JWT,\n and gateway bypasses per-service entitlement checks entirely.\n Intended for admin users only."
    },
    {
      "name": "namespace",
      "type": "string",
      "description": "namespace is the tenant namespace the policy assigns to this caller, as a\n leading-slash absolute path (e.g. \"/local/dev/acme\"). IDP+OPA live at the\n tenant level, so this is the tenant subtree the caller's issuer/claims map\n to. When empty, kernel falls back to the cluster-root namespace.",
      "constraints": [
