{
  "name": "ProxyPolicyEvalResult",
  "package": "proxypolicy",
  "description": "ProxyPolicyEvalResult is the output of the proxy policy OPA evaluation.\n Kernel reads this result and either rejects the request (allow = false) or\n mints an external token incorporating the specified mutations.",
  "fields": [
    {
      "name": "allow",
      "type": "bool",
      "description": "allow indicates whether the request is permitted.\n When false, kernel rejects the ExternalTokenMint call with PERMISSION_DENIED."
    },
    {
      "name": "url",
      "type": "string",
      "description": "url, if non-empty, is the resolved destination URL for the upstream request.\n Kernel returns this to the proxy in ExternalTokenMintResponse so the proxy\n forwards to the correct destination. Empty means the proxy uses its own\n DEFAULT_API_ENDPOINT for the service.",
      "constraints": [
        "maximum size: 2048 bytes",
        "must be a valid URL (scheme: URL_SCHEME_HTTP_OR_HTTPS)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 2048,
          "unit": "bytes",
          "source": "annotation"
        },
        {
          "rule": "assert_url",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "URL_SCHEME_HTTP_OR_HTTPS",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "reason",
      "type": "string",
      "description": "reason explains the denial. Returned to the proxy in the denial status.\n Empty when allow = true.",
      "constraints": [
        "maximum size: 512 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 512,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "append_aud",
      "type": "string",
      "description": "append_aud contains zero or more audience values to append to the minted\n external token's aud claim. The caller's original aud is always preserved —\n OPA may only add audiences, never replace or remove the original.\n Most policies leave this empty. Set it when the upstream requires a specific\n audience value (e.g. an OIDC client ID or SAML SP entity ID) in addition to\n the caller's existing aud.",
      "repeated": true,
      "constraints": [
        "maximum size: 8 elements",
        "maximum element size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 8,
          "unit": "elements",
          "source": "annotation"
        },
        {
          "rule": "default_max_element_size",
          "target": "element",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "extra_claims",
      "type": "message",
      "description": "extra_claims contains additional JWT claims to inject into the minted token.\n Kernel merges these into the token payload alongside the standard claims.\n Existing claims on the caller's token are never removed — only additions\n are permitted to prevent privilege escalation via claim stripping."
    },
    {
      "name": "auth_type",
      "type": "enum",
      "description": "auth_type determines the credential format kernel returns to the proxy.\n TOKEN_TYPE_JWT (default): kernel returns a signed JWT in the response.\n TOKEN_TYPE_SAML: kernel returns a SAML assertion in the response.\n Unset is treated as TOKEN_TYPE_JWT.",
      "enum_values": [
        {
          "name": "TOKEN_TYPE_JWT",
          "number": 1,
          "description": "TokenTypeJwt represents a JWT token"
        },
        {
          "name": "TOKEN_TYPE_SAML",
          "number": 2,
          "description": "TokenTypeSaml represents a SAML token"
        },
        {
          "name": "TOKEN_TYPE_SSH",
          "number": 3,
          "description": "TokenTypeSsh represents an SSH token"
        }
      ]
    },
    {
      "name": "token_use",
      "type": "enum",
      "description": "token_use sets the token_use claim on the minted external token.\n Must be TOKEN_USE_EXTERNAL or TOKEN_USE_UNSPECIFIED (both result in\n TOKEN_USE_EXTERNAL being stamped). Kernel rejects any other value to\n ensure external tokens can never be replayed against internal services.\n Policies should set this explicitly to TOKEN_USE_EXTERNAL to document intent.",
      "enum_values": [
        {
          "name": "TOKEN_USE_REFRESH",
          "number": 1
        },
        {
          "name": "TOKEN_USE_ACCESS",
          "number": 2
        },
        {
          "name": "TOKEN_USE_SERVICE",
          "number": 3
        },
        {
          "name": "TOKEN_USE_BOOTSTRAP",
          "number": 4
        },
        {
          "name": "TOKEN_USE_LOCALITY",
          "number": 5
        },
        {
          "name": "TOKEN_USE_EXTERNAL",
          "number": 6,
          "description": "TOKEN_USE_EXTERNAL marks a token minted by the token authority for use with an external upstream service.\n Internal service auth middleware rejects any token carrying this token_use value,\n preventing a compromised proxy from replaying an externally-minted credential\n against platform-internal services."
        },
        {
          "name": "TOKEN_USE_OFFLINE",
          "number": 7,
          "description": "TOKEN_USE_OFFLINE is the long-lived, identity-only Offline Token (OT) held\n by the client daemon on disk. Carries no entitlements (its long TTL would\n make an embedded entitlement snapshot lie). Used as input to mint AT, and to\n self-renew via TokenMint(input=OT, no aud)."
        }
      ]
    },
    {
      "name": "trace_id",
      "type": "string",
      "constraints": [
        "maximum size: 32768 bytes (default)"
      ],
      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "noop",
      "type": "bool"
    }
  ]
}
